@dataclass(order=True)
class JourneyNode:
    queue_key: tuple[float, int, int] = field(init=False, repr=False)
    lower_bound: float = field(compare=False)
    id: int = field(compare=False)
    depth: int = field(compare=False)
    branch_constraints: tuple[BranchConstraint, ...] = field(compare=False, default_factory=tuple)
    lower_bound_exact: bool = field(compare=False, default=False)
    priority_width: int = field(compare=False, default=0)

    def __post_init__(self) -> None:
        self.queue_key = (round(float(self.lower_bound), 9), int(self.priority_width), int(self.id))


@dataclass
class JourneyBranchStats:
    nodes_processed: int = 0
    rmp_solves: int = 0
    pricing_calls: int = 0
    exact_pricing_calls: int = 0
    generated_sequences: int = 0
    evaluated_timed_trips: int = 0
    dynamic_cuts_total: int = 0
    dynamic_subset_row_cuts_total: int = 0
    branch_nodes: int = 0
    pricing_incomplete_nodes: int = 0
    pool_integer_solves: int = 0
    restarts: int = 0


@dataclass
class _JourneySameDualSupplementResult:
    added: int = 0
    pricing_calls: int = 0
    exact_pricing_calls: int = 0
    generated_sequences: int = 0
    evaluated_timed_trips: int = 0
    priced_journeys: list[Any] = field(default_factory=list)
    changed_task_sets: list[frozenset[int]] = field(default_factory=list)


@dataclass
class _JourneyLearningRuntime:
    stabilizer: Any
    anchor: dict[int, float]
    objective_history: list[float]
    filter_true_rc: bool
    true_rc_tol: float
    true_rc_keep_threshold: float
    true_rc_fallback_keep_threshold: float
    true_rc_fallback_max_kept_per_round: int
    true_rc_max_kept_per_round: int
    stop_after_no_strong_round: bool
    min_kept_to_continue: int
    dual_center_enabled: bool = False
    dual_center_weight: float = 0.0
    dual_center_momentum: float = 0.25
    dual_center_min_rounds: int = 3
    dual_center: dict[int, float] | None = None
    dual_center_updates: int = 0
    pricing_rounds_used: int = 0
    suppress_after_no_strong_round: bool = False


@dataclass
class _JourneyDualAveragingRuntime:
    history: list[JourneyDuals] = field(default_factory=list)
    flat_rounds: int = 0
    true_rc_filter_failures: int = 0
    cooldown_until_iter: int = -1


@dataclass
class _JourneyGATAdmissionRuntime:
    queue: GATAdmissionQueue
    delayed_journeys: dict[str, Any] = field(default_factory=dict)


_JOURNEY_LEARNING_STABILIZER_CACHE: dict[tuple[Any, ...], Any] = {}
_JOURNEY_LEARNING_DEFAULT_PRICING_MAX_ROUNDS = 1
_JOURNEY_LEARNING_DEFAULT_TRUE_RC_MAX_KEPT_PER_ROUND = 4


def solve_bpc_future_journey(data: FutureData, config: dict[str, Any], *, logger: FutureLogger) -> FutureResult:
    _validate_journey_required_components(config)
    prewarmed_learning_runtime = _prewarm_journey_learning_runtime(data, config, logger)
    if bool(config.get("journey_branching_enabled", False)):
        return _solve_bpc_future_journey_branch_price(
            data,
            config,
            logger=logger,
            prewarmed_learning_runtime=prewarmed_learning_runtime,
        )

    started = time.perf_counter()
    time_limit = float(config.get("time_limit", 300.0))
    bucket = float(config.get("time_bucket_size", 10.0))
    start_step = float(config.get("pricing_start_time_step", bucket))
    integer_tol = float(config.get("integer_tol", 1.0e-6))
    eps = float(config.get("pricing_eps", 1.0e-6))

    from BPC_future.core.columns import TripPool

    trip_cache: dict[tuple, tuple] = {}
    resource_cache: dict[tuple, Any] = {}
    trip_pool = TripPool()
    _seed_initial_trips(data, trip_pool, bucket, start_step, int(config.get("initial_single_task_starts_per_task", 0)))
    composite_seed_added = _seed_initial_composite_trips(data, config, trip_pool, bucket, start_step, trip_cache=trip_cache)
    savings_seed_added = _seed_initial_savings_trips(data, config, trip_pool, bucket, trip_cache=trip_cache)
    journey_pool = JourneyPool()
    initial_source = _journey_source_trips(trip_pool.trips, int(config.get("journey_initial_source_trip_limit", 1200)))
    initial_journeys = build_journey_pool(
        data,
        initial_source,
        max_trips_per_journey=int(config.get("journey_pool_max_trips_per_journey", data.sortie_limit)),
        max_columns=int(config.get("journey_initial_max_columns", config.get("journey_pool_max_columns", 5000))),
        max_extensions_per_prefix=int(config.get("journey_pool_max_extensions_per_prefix", 80)),
    )
    for journey in initial_journeys.journeys:
        journey_pool.add(journey)
    cuts = _journey_static_cuts(data, config)
    cut_keys = {cut.key for cut in cuts}
    _log_journey_static_cut_diagnostics(logger, config, cuts, node_id=0, depth=0)

    logger.log(
        "start",
        instance=data.name,
        tasks=len(data.tasks),
        vehicles=len(data.vehicles),
        initial_trip_columns=len(trip_pool.trips),
        initial_composite_seed_added=composite_seed_added,
        initial_savings_seed_added=savings_seed_added,
        initial_journey_columns=len(journey_pool.journeys),
        time_bucket_size=bucket,
        master="journey_root",
        cuts_active=len(cuts),
    )
    incumbent = math.inf
    incumbent_solution: dict[int, list[Any]] = {}
    active_fleet_limit = len(data.vehicles)
    if _journey_initial_pool_integer_enabled(config):
        initial_mip = solve_journey_pool_master(
            data,
            journey_pool.journeys,
            solve_integer=True,
            time_limit=float(config.get("journey_pool_time_limit", 3.0)),
        )
        if initial_mip.mip_objective is not None:
            incumbent = float(initial_mip.mip_objective)
            incumbent_solution = _journey_assignment(initial_mip.selected_journeys)
            logger.log("incumbent", node_id=0, objective=round(incumbent, 6), vehicles=len(incumbent_solution), source="initial_journey_pool_mip")
            active_fleet_limit = _update_journey_fleet_limit(
                data,
                logger,
                active_fleet_limit,
                incumbent,
                incumbent_solution,
                0,
                slack=_journey_fleet_limit_slack(config),
            )
    else:
        logger.log("journey_initial_pool_integer", node_id=0, status="SKIPPED", reason="disabled")

    rmp_solves = 0
    pricing_calls = 0
    exact_pricing_calls = 0
    generated_sequences = 0
    evaluated_timed_trips = 0
    status = "TIME_LIMIT"
    dual_bound: float | None = None
    final_solution: dict[int, list[Any]] = incumbent_solution
    max_cg = int(config.get("journey_max_cg_iterations", config.get("max_cg_iterations", 100)))
    min_pricing_time = float(config.get("journey_min_pricing_time", 1.0e-3))
    post_pricing_reserve = max(0.0, float(config.get("journey_post_pricing_time_reserve", 2.0)))
    pool_probe_enabled = bool(config.get("journey_pool_integer_heuristic_enabled", config.get("pool_integer_heuristic_enabled", True)))
    pool_probe_frequency = max(1, int(config.get("journey_pool_integer_frequency", config.get("pool_integer_heuristic_frequency", 2))))
    heuristic_round_limit = int(config.get("journey_heuristic_max_rounds", config.get("heuristic_pricing_max_rounds", 0)))
    previous_dual_vector: tuple[float, ...] | None = None
    previous_pricing_duals: JourneyDuals | None = None
    dual_averaging_runtime = _JourneyDualAveragingRuntime()
    previous_rmp_objective: float | None = None
    previous_support_hash: str | None = None
    certificate_flat_rounds = 0
    certificate_no_column_rounds = 0
    certificate_flat_weak_column_rounds = 0
    restart_degenerate_rounds = 0
    restart_count = 0
    recent_priced_journeys: list[Any] = []
    recent_changed_task_sets: list[frozenset[int]] = []
    recent_worker_changed_task_sets: list[frozenset[int]] = []
    dynamic_cuts_total = 0
    dynamic_subset_row_cuts_total = 0
    learning_runtime: _JourneyLearningRuntime | None = prewarmed_learning_runtime
    learning_runtime_initialized = prewarmed_learning_runtime is not None
    learning_certificate_gate_logged = False
    sharded_pulse_audit_signal: dict[str, Any] | None = None
    sharded_pulse_worker_success_cooldown = 0
    sharded_pulse_worker_cooldown_reason = "success_cooldown"

    def _update_sharded_pulse_audit_signal(
        pulse_pricing: Any | None,
        *,
        node_id: int,
        depth: int,
        cg_iter: int,
    ) -> None:
        nonlocal sharded_pulse_audit_signal
        if pulse_pricing is None:
            return
        payload = getattr(pulse_pricing, "_sharded_pulse_audit_payload", None)
        if not isinstance(payload, dict):
            sharded_pulse_audit_signal = None
            return
        sharded_pulse_audit_signal = _journey_sharded_pulse_audit_signal_from_payload(
            payload,
            node_id=node_id,
            depth=depth,
            cg_iter=cg_iter,
        )

    for cg_iter in range(1, max_cg + 1):
        if time.perf_counter() - started >= time_limit:
            break
        active_fleet_limit = _update_journey_fleet_limit(
            data,
            logger,
            active_fleet_limit,
            incumbent,
            final_solution,
            cg_iter,
            slack=_journey_fleet_limit_slack(config),
        )
        solution = solve_journey_rmp(data, journey_pool.journeys, cuts=tuple(cuts), fleet_limit=active_fleet_limit)
        rmp_solves += 1
        logger.log(
            "journey_rmp",
            node_id=0,
            cg_iter=cg_iter,
            objective=None if solution.objective is None else round(float(solution.objective), 6),
            status=solution.status,
            journeys=len(journey_pool.journeys),
            variables=solution.variable_count,
            fleet_limit=active_fleet_limit,
        )
        if not solution.optimal or solution.duals is None or solution.objective is None:
            break
        dynamic_cuts_added = _separate_journey_subset_row_cuts(data, config, solution, cuts, cut_keys, logger, cg_iter)
        if dynamic_cuts_added > 0:
            dynamic_cuts_total += int(dynamic_cuts_added)
            dynamic_subset_row_cuts_total += int(dynamic_cuts_added)
            continue
        _log_journey_learning_dual_trace(
            data,
            config,
            logger,
            solution.duals,
            objective=float(solution.objective),
            cg_iter=cg_iter,
            node_id=0,
            depth=0,
        )
        scip_dual_vector = _journey_dual_vector(data, solution.duals, len(cuts))
        support_hash = _journey_support_hash(solution.journey_values)
        active_task_sets = _journey_active_task_sets(solution.journey_values)
        logger.log(
            "journey_pool_structure_diagnostics",
            node_id=0,
            depth=0,
            cg_iter=cg_iter,
            **_journey_pool_structure_diagnostics(journey_pool, solution.journey_values),
        )
        objective_delta = None if previous_rmp_objective is None else float(solution.objective) - float(previous_rmp_objective)
        scip_dual_l1_delta = None if previous_dual_vector is None else sum(abs(a - b) for a, b in zip(scip_dual_vector, previous_dual_vector))
        certificate_candidate = bool(
            math.isfinite(float(incumbent))
            and float(solution.objective) >= float(incumbent) - float(integer_tol)
        )
        if certificate_candidate and objective_delta is not None and abs(float(objective_delta)) <= max(eps, float(integer_tol)):
            certificate_flat_rounds += 1
        else:
            certificate_flat_rounds = 0
        progress_classification = _journey_progress_classification(
            objective_delta,
            scip_dual_l1_delta,
            previous_support_hash,
            support_hash,
            eps,
        )
        if progress_classification in {
            "dual_changed_degenerate",
            "support_changed_objective_flat",
            "stalled_same_dual_support",
        }:
            restart_degenerate_rounds += 1
        else:
            restart_degenerate_rounds = 0
        averaged_duals, averaged_dual_source = _journey_dual_averaging_pricing_duals(
            data,
            config,
            dual_averaging_runtime,
            solution.duals,
            objective_delta=objective_delta,
            progress_classification=progress_classification,
            logger=logger,
            cg_iter=cg_iter,
            node_id=0,
            depth=0,
        )
        if averaged_duals is not None and averaged_dual_source is not None:
            pricing_duals, pricing_dual_source = averaged_duals, averaged_dual_source
        else:
            pricing_duals, pricing_dual_source = _select_journey_pricing_duals(
                data,
                config,
                journey_pool,
                tuple(cuts),
                active_fleet_limit,
                float(solution.objective),
                solution.duals,
                previous_pricing_duals,
                logger,
                cg_iter,
                progress_classification=progress_classification,
                incumbent=incumbent,
                integer_tol=integer_tol,
                remaining_time=max(0.0, time_limit - (time.perf_counter() - started)),
                certificate_flat_rounds=certificate_flat_rounds,
                node_id=0,
                depth=0,
            )
        dual_vector = _journey_dual_vector(data, pricing_duals, len(cuts))
        dual_hash = _journey_dual_hash(dual_vector)
        dual_l1_delta = None if previous_dual_vector is None else sum(abs(a - b) for a, b in zip(dual_vector, previous_dual_vector))
        dual_linf_delta = None if previous_dual_vector is None else max(abs(a - b) for a, b in zip(dual_vector, previous_dual_vector))
        worker_changed_task_sets = {
            frozenset(int(task) for task in task_set)
            for task_set in recent_worker_changed_task_sets
        }
        worker_active_task_sets = worker_changed_task_sets.intersection(active_task_sets)
        worker_inactive_task_sets = worker_changed_task_sets.difference(active_task_sets)
        logger.log(
            "journey_rmp_dual_diagnostics",
            node_id=0,
            cg_iter=cg_iter,
            objective=round(float(solution.objective), 6),
            objective_delta=None if objective_delta is None else round(objective_delta, 9),
            dual_hash=dual_hash,
            dual_l1_delta=None if dual_l1_delta is None else round(dual_l1_delta, 9),
            dual_linf_delta=None if dual_linf_delta is None else round(dual_linf_delta, 9),
            active_journeys=len(solution.journey_values),
            active_support_hash=support_hash,
            worker_followup_changed_task_set_count=len(worker_changed_task_sets),
            worker_followup_active_changed_task_set_count=len(worker_active_task_sets),
            worker_followup_inactive_changed_task_set_count=len(worker_inactive_task_sets),
            worker_followup_changed_task_set_hash=_hash_strings(
                [
                    str(sorted(task_set))
                    for task_set in sorted(worker_changed_task_sets, key=lambda item: tuple(sorted(item)))
                ]
            ),
            worker_followup_active_changed_task_set_hash=_hash_strings(
                [
                    str(sorted(task_set))
                    for task_set in sorted(worker_active_task_sets, key=lambda item: tuple(sorted(item)))
                ]
            ),
        )
        recent_worker_changed_task_sets = []
        logger.log(
            "journey_cg_progress_diagnostics",
            node_id=0,
            cg_iter=cg_iter,
            classification=progress_classification,
            objective_delta=None if objective_delta is None else round(objective_delta, 9),
            dual_changed=None if dual_l1_delta is None else bool(dual_l1_delta > eps),
            scip_dual_l1_delta=None if scip_dual_l1_delta is None else round(scip_dual_l1_delta, 9),
            support_changed=None if previous_support_hash is None else bool(previous_support_hash != support_hash),
            dual_hash=dual_hash,
            pricing_dual_source=pricing_dual_source,
            active_support_hash=support_hash,
            certificate_candidate=certificate_candidate,
            certificate_flat_rounds=certificate_flat_rounds,
            certificate_flat_weak_column_rounds=certificate_flat_weak_column_rounds,
            restart_degenerate_rounds=restart_degenerate_rounds,
        )
        previous_dual_vector = dual_vector
        previous_pricing_duals = pricing_duals
        previous_rmp_objective = float(solution.objective)
        previous_support_hash = support_hash
        if _journey_lp_integral(solution.journey_values, integer_tol):
            old_incumbent = incumbent
            incumbent = min(incumbent, float(solution.objective))
            final_solution = _journey_assignment(solution.journey_values)
            updated_certificate_candidate = bool(
                math.isfinite(float(incumbent))
                and float(solution.objective) >= float(incumbent) - float(integer_tol)
            )
            if updated_certificate_candidate and not certificate_candidate:
                logger.log(
                    "journey_certificate_candidate_updated",
                    node_id=0,
                    cg_iter=cg_iter,
                    reason="integral_rmp_incumbent",
                    old_incumbent=None if old_incumbent == math.inf else round(float(old_incumbent), 6),
                    incumbent=round(float(incumbent), 6),
                    rmp_objective=round(float(solution.objective), 6),
                )
            certificate_candidate = updated_certificate_candidate
        pricing = None
        base_heuristic_allowed = (
            bool(config.get("journey_heuristic_pricing_enabled", True))
            and (heuristic_round_limit <= 0 or cg_iter <= heuristic_round_limit)
        )
        learning_certificate_disabled = _journey_learning_certificate_gate_disabled(config, certificate_candidate)
        if (
            not learning_runtime_initialized
            and learning_certificate_disabled
            and bool(config.get("journey_learning_enabled", False))
            and not learning_certificate_gate_logged
        ):
            logger.log(
                "journey_learning",
                node_id=0,
                depth=0,
                cg_iter=cg_iter,
                status="DISABLED",
                reason="certificate_candidate_gate",
                certificate_candidate=bool(certificate_candidate),
            )
            learning_certificate_gate_logged = True
        if (
            not learning_runtime_initialized
            and not learning_certificate_disabled
            and bool(config.get("journey_learning_enabled", False))
        ):
            learning_runtime = _maybe_create_journey_learning_runtime(data, config, logger, node_id=0, depth=0)
            learning_runtime_initialized = True
        active_learning_runtime = _journey_learning_runtime_for_pricing(
            learning_runtime,
            config,
            cg_iter=cg_iter,
            certificate_disabled=learning_certificate_disabled,
        )
        learning_heuristic_allowed = active_learning_runtime is not None
        heuristic_allowed = bool(base_heuristic_allowed or learning_heuristic_allowed)
        sharded_pulse_worker_attempted_before_heuristic = False
        if bool(config.get("journey_sharded_pulse_hidden_negative_worker_before_heuristic_enabled", False)):
            sharded_pulse_worker_attempted_before_heuristic = True
            remaining = max(0.0, time_limit - (time.perf_counter() - started))
            if remaining > min_pricing_time:
                pre_worker_base_config = _journey_pricing_config(
                    data,
                    config,
                    bucket,
                    start_step,
                    eps,
                    remaining,
                    heuristic=False,
                    cg_iter=cg_iter,
                )
                if sharded_pulse_worker_success_cooldown > 0:
                    forbidden_signatures = _journey_forbidden_signatures_for_node(journey_pool, tuple())
                    context_hashes = _journey_sharded_pulse_audit_context_hashes(
                        data,
                        solution.duals,
                        tuple(),
                        tuple(cuts),
                        forbidden_signatures,
                    )
                    _log_journey_sharded_pulse_worker_skipped(
                        logger,
                        config,
                        skip_reason=sharded_pulse_worker_cooldown_reason or "success_cooldown",
                        trigger=str(
                            config.get(
                                "journey_sharded_pulse_hidden_negative_worker_trigger",
                                "before_legacy_final_judge",
                            )
                        ),
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        context_hashes=context_hashes,
                    )
                    sharded_pulse_worker_success_cooldown -= 1
                    if sharded_pulse_worker_success_cooldown <= 0:
                        sharded_pulse_worker_cooldown_reason = "success_cooldown"
                else:
                    hidden_worker = _run_journey_sharded_pulse_hidden_negative_worker(
                        data,
                        config,
                        logger,
                        duals=solution.duals,
                        branch_constraints=tuple(),
                        cuts=tuple(cuts),
                        journey_pool=journey_pool,
                        base_pricing_config=pre_worker_base_config,
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        active_task_sets=active_task_sets,
                        certificate_candidate=certificate_candidate,
                        remaining_time=remaining,
                        previous_audit_signal=_journey_sharded_pulse_audit_signal_valid_for_worker(
                            sharded_pulse_audit_signal,
                            node_id=0,
                            depth=0,
                            cg_iter=cg_iter,
                            max_age=int(
                                config.get(
                                    "journey_sharded_pulse_hidden_negative_worker_audit_signal_max_age",
                                    3,
                                )
                            ),
                        ),
                        previous_audit_context_hashes=None
                        if sharded_pulse_audit_signal is None
                        else dict(sharded_pulse_audit_signal.get("context_hashes", {})),
                        certificate_flat_rounds=certificate_flat_rounds,
                        certificate_no_column_rounds=certificate_no_column_rounds,
                    )
                    if hidden_worker is not None:
                        worker_pricing, worker_pricing_config = hidden_worker
                        pricing_calls += 1
                        exact_pricing_calls += 1
                        generated_sequences += int(worker_pricing.generated_sequences)
                        evaluated_timed_trips += int(worker_pricing.evaluated_timed_trips)
                        _log_journey_pricing(
                            logger,
                            worker_pricing,
                            cg_iter,
                            pricing_kind="sharded_pulse_hidden_negative_worker",
                            config=worker_pricing_config,
                            pricing_dual_source="scip",
                        )
                        _log_journey_counterfactual_replay_capture(
                            logger,
                            data,
                            config,
                            worker_pricing,
                            solution.duals,
                            tuple(cuts),
                            tuple(),
                            journey_pool,
                            pricing_config=worker_pricing_config,
                            pricing_kind="sharded_pulse_hidden_negative_worker",
                            cg_iter=cg_iter,
                            rmp_objective=float(solution.objective),
                            active_task_sets=active_task_sets,
                            active_variable_values=getattr(solution, "variable_values", None),
                            active_reduced_costs=getattr(solution, "reduced_costs", None),
                            pricing_dual_source="scip",
                        )
                        if worker_pricing.journeys:
                            _log_journey_gat_target_mode_shadow(
                                logger,
                                worker_pricing.journeys,
                                solution.duals,
                                tuple(cuts),
                                config,
                                cg_iter=cg_iter,
                                node_id=0,
                                depth=0,
                                pricing_kind="sharded_pulse_hidden_negative_worker",
                                certificate_candidate=certificate_candidate,
                            )
                            added = _add_priced_journeys(journey_pool, worker_pricing.journeys)
                            _log_journey_addition(
                                logger,
                                worker_pricing,
                                added,
                                cg_iter,
                                pricing_kind="sharded_pulse_hidden_negative_worker",
                                active_task_sets=active_task_sets,
                            )
                            if int(added) > 0:
                                sharded_pulse_worker_success_cooldown = (
                                    _journey_sharded_pulse_worker_success_cooldown_rounds(
                                        config,
                                        added,
                                        active_task_sets=active_task_sets,
                                    )
                                )
                                sharded_pulse_worker_cooldown_reason = "success_cooldown"
                                certificate_no_column_rounds = 0
                                recent_priced_journeys = list(worker_pricing.journeys)
                                recent_changed_task_sets = list(getattr(added, "changed_task_sets", tuple()))
                                recent_worker_changed_task_sets = list(
                                    getattr(added, "changed_task_sets", tuple())
                                )
                                if not bool(
                                    config.get(
                                        "journey_sharded_pulse_hidden_negative_worker_continue_same_iteration_after_add",
                                        False,
                                    )
                                ):
                                    continue
                                logger.log(
                                    "journey_sharded_pulse_worker_continue_same_iteration",
                                    node_id=0,
                                    depth=0,
                                    cg_iter=cg_iter,
                                    pricing_kind="sharded_pulse_hidden_negative_worker",
                                    added_journeys=int(added),
                                    next_stage="heuristic",
                                )
                            else:
                                sharded_pulse_worker_success_cooldown = (
                                    _journey_sharded_pulse_worker_failure_cooldown_rounds(
                                        config,
                                        worker_pricing,
                                        added=added,
                                    )
                                )
                                if sharded_pulse_worker_success_cooldown > 0:
                                    sharded_pulse_worker_cooldown_reason = "failure_cooldown"
                        else:
                            sharded_pulse_worker_success_cooldown = (
                                _journey_sharded_pulse_worker_failure_cooldown_rounds(
                                    config,
                                    worker_pricing,
                                )
                            )
                            if sharded_pulse_worker_success_cooldown > 0:
                                sharded_pulse_worker_cooldown_reason = "failure_cooldown"
        if heuristic_allowed:
            remaining = max(0.0, time_limit - (time.perf_counter() - started))
            if remaining <= min_pricing_time:
                break
            heuristic_pricing_config = _journey_pricing_config(
                data,
                config,
                bucket,
                start_step,
                eps,
                remaining,
                heuristic=True,
                cg_iter=cg_iter,
            )
            heuristic_duals, heuristic_dual_source, learning_smoothed = _journey_learning_pricing_duals(
                active_learning_runtime,
                solution.duals,
                rmp_objective=float(solution.objective),
                branch_depth=0,
                logger=logger,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
            )
            if not learning_smoothed:
                heuristic_duals, heuristic_dual_source = pricing_duals, pricing_dual_source
            if not learning_smoothed and not base_heuristic_allowed:
                logger.log(
                    "journey_learning_smoothing",
                    node_id=0,
                    depth=0,
                    cg_iter=cg_iter,
                    status="SKIPPED",
                    reason="learning_not_active_and_base_heuristic_disabled",
                )
            else:
                if learning_smoothed:
                    heuristic_pricing_config = _journey_learning_pricing_config(config, heuristic_pricing_config)
                heuristic_trip_cache, heuristic_resource_cache = _journey_pricing_caches_for_learning_pass(
                    learning_smoothed=learning_smoothed,
                    trip_cache=trip_cache,
                    resource_cache=resource_cache,
                )
                pricing = price_journeys(
                    data,
                    heuristic_duals,
                    tuple(),
                    config=heuristic_pricing_config,
                    cuts=tuple(cuts),
                    trip_cache=heuristic_trip_cache,
                    resource_cache=heuristic_resource_cache,
                    forbidden_journey_signatures=_journey_forbidden_signatures_for_node(journey_pool, tuple()),
                    dominant_task_set_costs=_journey_pricing_dominant_task_set_costs(journey_pool, cuts, tuple()),
                )
                pricing_calls += 1
                generated_sequences += pricing.generated_sequences
                evaluated_timed_trips += pricing.evaluated_timed_trips
                _log_journey_pricing(
                    logger,
                    pricing,
                    cg_iter,
                    pricing_kind="heuristic",
                    config=heuristic_pricing_config,
                    pricing_dual_source=heuristic_dual_source,
                )
                _log_journey_counterfactual_replay_capture(
                    logger,
                    data,
                    config,
                    pricing,
                    solution.duals,
                    tuple(cuts),
                    tuple(),
                    journey_pool,
                    pricing_config=heuristic_pricing_config,
                    pricing_kind="heuristic",
                    cg_iter=cg_iter,
                    rmp_objective=float(solution.objective),
                    active_task_sets=active_task_sets,
                    active_variable_values=getattr(solution, "variable_values", None),
                    active_reduced_costs=getattr(solution, "reduced_costs", None),
                    pricing_dual_source=heuristic_dual_source,
                )
                _log_journey_pulse_residual_replay_diagnostic(
                    logger,
                    data,
                    config,
                    pricing,
                    solution.duals,
                    tuple(cuts),
                    pricing_config=heuristic_pricing_config,
                    pricing_kind="heuristic",
                    cg_iter=cg_iter,
                    node_id=0,
                    depth=0,
                )
                priced_journeys = pricing.journeys
                if learning_smoothed and learning_runtime is not None and learning_runtime.filter_true_rc:
                    (
                        learning_keep_threshold,
                        learning_max_kept,
                        learning_fallback_keep_threshold,
                        learning_fallback_max_kept,
                        learning_filter_context,
                    ) = _journey_learning_true_rc_filter_parameters(
                        config,
                        learning_runtime,
                        certificate_candidate=certificate_candidate,
                    )
                    priced_journeys = _journey_learning_true_rc_filter(
                        logger,
                        pricing.journeys,
                        true_duals=solution.duals,
                        cuts=tuple(cuts),
                        tol=learning_runtime.true_rc_tol if learning_runtime is not None else 1.0e-5,
                        keep_threshold=learning_keep_threshold,
                        max_kept=learning_max_kept,
                        fallback_keep_threshold=learning_fallback_keep_threshold,
                        fallback_max_kept=learning_fallback_max_kept,
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        pricing_kind="heuristic",
                        filter_context=learning_filter_context,
                    )
                if priced_journeys:
                    pricing_for_add = replace(pricing, journeys=list(priced_journeys))
                    _log_journey_gat_target_mode_shadow(
                        logger,
                        list(priced_journeys),
                        solution.duals,
                        tuple(cuts),
                        config,
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        pricing_kind="heuristic",
                        certificate_candidate=certificate_candidate,
                    )
                    if learning_smoothed and learning_runtime is not None and learning_runtime.filter_true_rc:
                        seed_config = _journey_pricing_config(
                            data,
                            config,
                            bucket,
                            start_step,
                            eps,
                            remaining,
                            heuristic=False,
                            cg_iter=cg_iter,
                        )
                        _seed_hidden_negative_profile_catalog(
                            logger,
                            data,
                            config,
                            pricing_for_add,
                            solution.duals,
                            seed_config,
                            trip_cache,
                            tuple(),
                            cg_iter,
                            pricing_kind="heuristic_learning_true_rc",
                            node_id=0,
                            depth=0,
                        )
                    added = _add_priced_journeys(journey_pool, list(priced_journeys))
                    flat_weak_addition = _journey_flat_weak_column_pressure_addition(
                        config,
                        added,
                        certificate_candidate=certificate_candidate,
                        certificate_flat_rounds=certificate_flat_rounds,
                        objective_delta=objective_delta,
                        eps=eps,
                        active_task_sets=active_task_sets,
                    )
                    if flat_weak_addition:
                        certificate_flat_weak_column_rounds += 1
                    else:
                        certificate_flat_weak_column_rounds = 0
                    _log_journey_addition(
                        logger,
                        pricing_for_add,
                        added,
                        cg_iter,
                        pricing_kind="heuristic",
                        active_task_sets=active_task_sets,
                    )
                    if learning_smoothed and learning_runtime is not None:
                        _journey_learning_handle_smoothed_pricing_result(
                            logger,
                            learning_runtime,
                            found_negative_column=added > 0,
                            candidate_journeys=len(pricing.journeys),
                            kept_journeys=len(priced_journeys),
                            added_journeys=added,
                            cg_iter=cg_iter,
                            node_id=0,
                            depth=0,
                            pricing_kind="heuristic",
                        )
                    if added > 0 and _should_run_journey_pool_probe(pool_probe_enabled, cg_iter, pool_probe_frequency):
                        incumbent, final_solution = _run_journey_pool_incumbent_probe(
                            data,
                            config,
                            journey_pool,
                            logger,
                            cg_iter,
                            incumbent,
                            final_solution,
                            fleet_limit=active_fleet_limit,
                            remaining=max(0.0, time_limit - (time.perf_counter() - started)),
                        )
                    active_fleet_limit = _update_journey_fleet_limit(
                        data,
                        logger,
                        active_fleet_limit,
                        incumbent,
                        final_solution,
                        cg_iter,
                        slack=_journey_fleet_limit_slack(config),
                    )
                    if added > 0:
                        logger.log(
                            "journey_flat_weak_column_pressure",
                            node_id=0,
                            depth=0,
                            cg_iter=cg_iter,
                            pricing_kind="heuristic",
                            weak=bool(flat_weak_addition),
                            flat_weak_column_rounds=int(certificate_flat_weak_column_rounds),
                            certificate_flat_rounds=int(certificate_flat_rounds),
                            objective_delta=None if objective_delta is None else round(float(objective_delta), 9),
                            added_journeys=int(added),
                            new_journeys=int(getattr(added, "new_journeys", int(added))),
                            replacement_journeys=int(getattr(added, "replacement_journeys", 0)),
                            continue_exact=bool(
                                flat_weak_addition
                                and _journey_continue_exact_after_flat_weak_heuristic(
                                    config,
                                    flat_weak_column_rounds=certificate_flat_weak_column_rounds,
                                )
                            ),
                        )
                        if not bool(flat_weak_addition):
                            certificate_no_column_rounds = 0
                            continue
                        if not _journey_continue_exact_after_flat_weak_heuristic(
                            config,
                            flat_weak_column_rounds=certificate_flat_weak_column_rounds,
                        ):
                            continue
                elif learning_smoothed and learning_runtime is not None:
                    _journey_learning_handle_smoothed_pricing_result(
                        logger,
                        learning_runtime,
                        found_negative_column=False,
                        candidate_journeys=len(pricing.journeys),
                        kept_journeys=0,
                        added_journeys=0,
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        pricing_kind="heuristic",
                    )
        remaining = max(0.0, time_limit - (time.perf_counter() - started))
        if remaining <= min_pricing_time:
            break
        exact_budget, reserve_used, budget_reason = _journey_exact_pricing_budget(
            remaining=remaining,
            post_pricing_reserve=post_pricing_reserve,
            min_pricing_time=min_pricing_time,
            incumbent=incumbent,
            rmp_objective=float(solution.objective),
            integer_tol=integer_tol,
            cg_iter=cg_iter,
            certificate_no_reserve_enabled=bool(config.get("journey_certificate_no_reserve_enabled", True)),
            certificate_no_reserve_min_cg_iter=int(config.get("journey_certificate_no_reserve_min_cg_iter", 3)),
            deadline_safety_margin=float(config.get("journey_pricing_deadline_safety_margin", 1.0)),
        )
        logger.log(
            "journey_exact_pricing_budget",
            node_id=0,
            cg_iter=cg_iter,
            remaining=round(float(remaining), 6),
            exact_budget=round(float(exact_budget), 6),
            post_pricing_reserve=round(float(post_pricing_reserve), 6),
            reserve_used=round(float(reserve_used), 6),
            reason=budget_reason,
            incumbent=None if incumbent == math.inf else round(float(incumbent), 6),
            rmp_objective=round(float(solution.objective), 6),
        )
        exact_pricing_config = _journey_pricing_config(
            data,
            config,
            bucket,
            start_step,
            eps,
            exact_budget,
            heuristic=False,
            cg_iter=cg_iter,
        )
        exact_pricing_config, certificate_pricing_mode = _journey_certificate_pricing_config(
            config,
            exact_pricing_config,
            certificate_candidate=certificate_candidate,
            certificate_flat_rounds=certificate_flat_rounds,
            certificate_no_column_rounds=certificate_no_column_rounds,
            depth=0,
        )
        exact_pricing_config, immediate_no_reserve = _journey_immediate_certificate_no_reserve_config(
            config,
            exact_pricing_config,
            certificate_candidate=certificate_candidate,
            budget_reason=budget_reason,
            exact_budget=exact_budget,
        )
        if immediate_no_reserve:
            logger.log(
                "journey_certificate_immediate_no_reserve",
                node_id=0,
                cg_iter=cg_iter,
                time_limit=round(float(exact_pricing_config.time_limit), 6),
                profile_generation_time_fraction=round(float(exact_pricing_config.profile_generation_time_fraction), 6),
            )
        if certificate_pricing_mode.get("fast_negative_return"):
            logger.log(
                "journey_certificate_fast_negative_return",
                node_id=0,
                cg_iter=cg_iter,
                certificate_flat_rounds=certificate_flat_rounds,
                early_return_negative=bool(exact_pricing_config.early_return_negative),
                early_return_negative_min_count=int(exact_pricing_config.early_return_negative_min_count),
                streaming_min_negative_batch=int(exact_pricing_config.streaming_min_negative_batch),
                remaining=round(float(remaining), 6),
            )
        if certificate_pricing_mode.get("full_scan"):
            logger.log(
                "journey_certificate_full_scan",
                node_id=0,
                cg_iter=cg_iter,
                certificate_flat_rounds=certificate_flat_rounds,
                full_scan_after=int(certificate_pricing_mode.get("full_scan_after", 0)),
                streaming_pricing_enabled=False,
                early_return_negative=False,
                max_sequences=int(exact_pricing_config.max_sequences),
                max_timed_evaluations=int(exact_pricing_config.max_timed_evaluations),
                remaining=round(float(remaining), 6),
            )

        def audit_final_legacy_pricing(current_pricing: Any) -> None:
            audit_pricing = _run_journey_sharded_pulse_audit(
                data,
                config,
                logger,
                legacy_pricing=current_pricing,
                legacy_duals=solution.duals,
                branch_constraints=tuple(),
                cuts=tuple(cuts),
                journey_pool=journey_pool,
                base_pricing_config=exact_pricing_config,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                active_task_sets=active_task_sets,
                trigger="after_legacy_final_judge",
            )
            _update_sharded_pulse_audit_signal(
                audit_pricing,
                node_id=0,
                depth=0,
                cg_iter=cg_iter,
            )

        exact_duals, exact_dual_source = _journey_exact_pricing_duals(
            solution.duals,
            pricing_duals,
            pricing_dual_source,
            learning_runtime=learning_runtime,
            certificate_candidate=certificate_candidate,
            completion_bound_enabled=exact_pricing_config.direct_journey_label_completion_bound_enabled,
        )
        exact_pricing_kind = "exact"
        if exact_dual_source == "dual_average":
            average_direct_config, average_direct_mode = _journey_dual_average_direct_patrol_config(
                config,
                exact_pricing_config,
                remaining=remaining,
                min_pricing_time=min_pricing_time,
            )
            if average_direct_mode:
                logger.log(
                    "journey_dual_averaging_direct_patrol",
                    node_id=0,
                    depth=0,
                    cg_iter=cg_iter,
                    remaining=round(float(remaining), 6),
                    patrol_mode=average_direct_mode,
                    pricing_dual_source=exact_dual_source,
                    certificate_capable=False,
                )
                exact_pricing_config = average_direct_config
                exact_pricing_kind = "exact_dual_average_direct_patrol"
        if sharded_pulse_worker_attempted_before_heuristic:
            hidden_worker = None
        elif sharded_pulse_worker_success_cooldown > 0:
            forbidden_signatures = _journey_forbidden_signatures_for_node(journey_pool, tuple())
            context_hashes = _journey_sharded_pulse_audit_context_hashes(
                data,
                solution.duals,
                tuple(),
                tuple(cuts),
                forbidden_signatures,
            )
            _log_journey_sharded_pulse_worker_skipped(
                logger,
                config,
                skip_reason=sharded_pulse_worker_cooldown_reason or "success_cooldown",
                trigger=str(
                    config.get(
                        "journey_sharded_pulse_hidden_negative_worker_trigger",
                        "before_legacy_final_judge",
                    )
                ),
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                context_hashes=context_hashes,
            )
            sharded_pulse_worker_success_cooldown -= 1
            if sharded_pulse_worker_success_cooldown <= 0:
                sharded_pulse_worker_cooldown_reason = "success_cooldown"
            hidden_worker = None
        else:
            hidden_worker = _run_journey_sharded_pulse_hidden_negative_worker(
                data,
                config,
                logger,
                duals=solution.duals,
                branch_constraints=tuple(),
                cuts=tuple(cuts),
                journey_pool=journey_pool,
                base_pricing_config=exact_pricing_config,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                active_task_sets=active_task_sets,
                certificate_candidate=certificate_candidate,
                remaining_time=remaining,
                previous_audit_signal=_journey_sharded_pulse_audit_signal_valid_for_worker(
                    sharded_pulse_audit_signal,
                    node_id=0,
                    depth=0,
                    cg_iter=cg_iter,
                    max_age=int(
                        config.get(
                            "journey_sharded_pulse_hidden_negative_worker_audit_signal_max_age",
                            3,
                        )
                    ),
                ),
                previous_audit_context_hashes=None
                if sharded_pulse_audit_signal is None
                else dict(sharded_pulse_audit_signal.get("context_hashes", {})),
                certificate_flat_rounds=certificate_flat_rounds,
                certificate_no_column_rounds=certificate_no_column_rounds,
            )
        if hidden_worker is not None:
            worker_pricing, worker_pricing_config = hidden_worker
            pricing_calls += 1
            exact_pricing_calls += 1
            generated_sequences += int(worker_pricing.generated_sequences)
            evaluated_timed_trips += int(worker_pricing.evaluated_timed_trips)
            _log_journey_pricing(
                logger,
                worker_pricing,
                cg_iter,
                pricing_kind="sharded_pulse_hidden_negative_worker",
                config=worker_pricing_config,
                pricing_dual_source="scip",
            )
            _log_journey_counterfactual_replay_capture(
                logger,
                data,
                config,
                worker_pricing,
                solution.duals,
                tuple(cuts),
                tuple(),
                journey_pool,
                pricing_config=worker_pricing_config,
                pricing_kind="sharded_pulse_hidden_negative_worker",
                cg_iter=cg_iter,
                rmp_objective=float(solution.objective),
                active_task_sets=active_task_sets,
                active_variable_values=getattr(solution, "variable_values", None),
                active_reduced_costs=getattr(solution, "reduced_costs", None),
                pricing_dual_source="scip",
            )
            if worker_pricing.journeys:
                _log_journey_gat_target_mode_shadow(
                    logger,
                    worker_pricing.journeys,
                    solution.duals,
                    tuple(cuts),
                    config,
                    cg_iter=cg_iter,
                    node_id=0,
                    depth=0,
                    pricing_kind="sharded_pulse_hidden_negative_worker",
                    certificate_candidate=certificate_candidate,
                )
                added = _add_priced_journeys(journey_pool, worker_pricing.journeys)
                _log_journey_addition(
                    logger,
                    worker_pricing,
                    added,
                    cg_iter,
                    pricing_kind="sharded_pulse_hidden_negative_worker",
                    active_task_sets=active_task_sets,
                )
                if int(added) > 0:
                    sharded_pulse_worker_success_cooldown = (
                        _journey_sharded_pulse_worker_success_cooldown_rounds(
                            config,
                            added,
                            active_task_sets=active_task_sets,
                        )
                    )
                    sharded_pulse_worker_cooldown_reason = "success_cooldown"
                    certificate_no_column_rounds = 0
                    recent_priced_journeys = list(worker_pricing.journeys)
                    recent_changed_task_sets = list(getattr(added, "changed_task_sets", tuple()))
                    recent_worker_changed_task_sets = list(getattr(added, "changed_task_sets", tuple()))
                    continue
                sharded_pulse_worker_success_cooldown = (
                    _journey_sharded_pulse_worker_failure_cooldown_rounds(
                        config,
                        worker_pricing,
                        added=added,
                    )
                )
                if sharded_pulse_worker_success_cooldown > 0:
                    sharded_pulse_worker_cooldown_reason = "failure_cooldown"
            else:
                sharded_pulse_worker_success_cooldown = (
                    _journey_sharded_pulse_worker_failure_cooldown_rounds(
                        config,
                        worker_pricing,
                    )
                )
                if sharded_pulse_worker_success_cooldown > 0:
                    sharded_pulse_worker_cooldown_reason = "failure_cooldown"
        pricing = price_journeys(
            data,
            exact_duals,
            tuple(),
            config=exact_pricing_config,
            cuts=tuple(cuts),
            trip_cache=trip_cache,
            resource_cache=resource_cache,
            forbidden_journey_signatures=_journey_forbidden_signatures_for_node(journey_pool, tuple()),
            dominant_task_set_costs=_journey_pricing_dominant_task_set_costs(journey_pool, cuts, tuple()),
            priority_task_sets=active_task_sets,
            active_support_task_sets=active_task_sets,
        )
        if exact_dual_source == "dual_average":
            pricing = _journey_dual_average_true_rc_filtered_pricing(
                logger,
                pricing,
                runtime=dual_averaging_runtime,
                true_duals=solution.duals,
                cuts=tuple(cuts),
                config=config,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                pricing_kind=exact_pricing_kind,
            )
        pricing_calls += 1
        exact_pricing_calls += 1
        generated_sequences += pricing.generated_sequences
        evaluated_timed_trips += pricing.evaluated_timed_trips
        _log_journey_pricing(
            logger,
            pricing,
            cg_iter,
            pricing_kind=exact_pricing_kind,
            config=exact_pricing_config,
            pricing_dual_source=exact_dual_source,
        )
        _log_journey_counterfactual_replay_capture(
            logger,
            data,
            config,
            pricing,
            solution.duals,
            tuple(cuts),
            tuple(),
            journey_pool,
            pricing_config=exact_pricing_config,
            pricing_kind=exact_pricing_kind,
            cg_iter=cg_iter,
            rmp_objective=float(solution.objective),
            active_task_sets=active_task_sets,
            active_variable_values=getattr(solution, "variable_values", None),
            active_reduced_costs=getattr(solution, "reduced_costs", None),
            pricing_dual_source=exact_dual_source,
        )
        audit_ran_for_pricing = False
        audit_trigger = str(
            config.get("journey_sharded_pulse_audit_trigger", "after_legacy_final_judge") or ""
        ).strip().lower()
        if bool(config.get("journey_sharded_pulse_audit_force_on_root", False)) or audit_trigger == "after_each_final_pricing":
            audit_pricing = _run_journey_sharded_pulse_audit(
                data,
                config,
                logger,
                legacy_pricing=pricing,
                legacy_duals=solution.duals,
                branch_constraints=tuple(),
                cuts=tuple(cuts),
                journey_pool=journey_pool,
                base_pricing_config=exact_pricing_config,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                active_task_sets=active_task_sets,
                trigger="after_each_final_pricing",
            )
            _update_sharded_pulse_audit_signal(
                audit_pricing,
                node_id=0,
                depth=0,
                cg_iter=cg_iter,
            )
            audit_ran_for_pricing = True
        if pricing.journeys:
            if not audit_ran_for_pricing:
                audit_final_legacy_pricing(pricing)
            _log_journey_gat_target_mode_shadow(
                logger,
                pricing.journeys,
                solution.duals,
                tuple(cuts),
                config,
                cg_iter=cg_iter,
                node_id=0,
                depth=0,
                pricing_kind=exact_pricing_kind,
                certificate_candidate=certificate_candidate,
            )
            added = _add_priced_journeys(journey_pool, pricing.journeys)
            _log_journey_addition(
                logger,
                pricing,
                added,
                cg_iter,
                pricing_kind=exact_pricing_kind,
                active_task_sets=active_task_sets,
            )
            if added > 0:
                recent_priced_journeys = list(pricing.journeys)
                recent_changed_task_sets = list(getattr(added, "changed_task_sets", tuple()))
                if _journey_same_dual_supplement_needed(
                    config,
                    added_columns=int(added),
                    certificate_candidate=certificate_candidate,
                    certificate_flat_rounds=certificate_flat_rounds,
                    depth=0,
                    pricing_dual_source=exact_dual_source,
                ):
                    supplement = _run_journey_same_dual_supplement(
                        data,
                        config,
                        journey_pool,
                        exact_pricing_config,
                        exact_duals,
                        tuple(cuts),
                        tuple(),
                        logger,
                        cg_iter,
                        node_id=0,
                        depth=0,
                        deadline=started + time_limit,
                        min_pricing_time=min_pricing_time,
                        trip_cache=trip_cache,
                        resource_cache=resource_cache,
                        active_task_sets=active_task_sets,
                        previous_pricing_kind=exact_pricing_kind,
                        previous_added=int(added),
                        pricing_dual_source=exact_dual_source,
                    )
                    pricing_calls += int(supplement.pricing_calls)
                    exact_pricing_calls += int(supplement.exact_pricing_calls)
                    generated_sequences += int(supplement.generated_sequences)
                    evaluated_timed_trips += int(supplement.evaluated_timed_trips)
                    if int(supplement.added) > 0:
                        added += int(supplement.added)
                        recent_priced_journeys.extend(supplement.priced_journeys)
                        recent_changed_task_sets.extend(supplement.changed_task_sets)
            if added > 0 and _should_run_journey_pool_probe(pool_probe_enabled, cg_iter, pool_probe_frequency):
                incumbent, final_solution = _run_journey_pool_incumbent_probe(
                    data,
                    config,
                    journey_pool,
                    logger,
                    cg_iter,
                    incumbent,
                    final_solution,
                    fleet_limit=active_fleet_limit,
                    remaining=max(0.0, time_limit - (time.perf_counter() - started)),
                )
                active_fleet_limit = _update_journey_fleet_limit(
                    data,
                    logger,
                    active_fleet_limit,
                    incumbent,
                    final_solution,
                    cg_iter,
                    slack=_journey_fleet_limit_slack(config),
                )
            if added > 0:
                certificate_no_column_rounds = 0
                journey_pool, restarted = _maybe_restart_journey_pool(
                    data,
                    config,
                    journey_pool,
                    solution,
                    final_solution,
                    recent_priced_journeys,
                    logger,
                    cg_iter,
                    certificate_flat_rounds,
                    restart_count,
                    progress_classification=progress_classification,
                    degenerate_rounds=restart_degenerate_rounds,
                    node_id=0,
                    depth=0,
                )
                restart_count += int(restarted)
                continue
            logger.log(
                "journey_pricing_duplicate_block",
                node_id=0,
                cg_iter=cg_iter,
                pricing_kind="exact",
                exhausted=pricing.exhausted,
                reason="negative_journey_already_in_pool",
                rmp_objective=round(float(solution.objective), 9),
                dual_hash=dual_hash,
                pricing_status=pricing.status,
                pricing_reason=pricing.reason,
                existing_journeys_filtered=getattr(pricing, "existing_journeys_filtered", 0),
                **_journey_duplicate_diagnostics(journey_pool, getattr(pricing, "journeys", []) or [], exact_duals, tuple(cuts)),
            )
            break
        if not pricing.exhausted:
            certificate_no_column_rounds += 1
            retry_enabled = bool(config.get("journey_retry_incomplete_no_column_enabled", True))
            skip_ordinary_retry_for_final_probe = _journey_skip_ordinary_retry_after_profile_materialization_failure(
                config,
                pricing,
            )
            skip_reason = (
                "profile_materialization_failure_goes_to_final_probe"
                if bool(skip_ordinary_retry_for_final_probe)
                else ""
            )
            retry_min_time = float(config.get("journey_retry_incomplete_no_column_min_time", 1.0))
            retry_remaining = max(0.0, time_limit - (time.perf_counter() - started))
            if not bool(skip_ordinary_retry_for_final_probe) and _journey_skip_ordinary_retry_after_weak_negative_filtered(
                config,
                pricing,
            ):
                final_probe_config, _final_probe_mode = _journey_certificate_pricing_config(
                    config,
                    exact_pricing_config,
                    certificate_candidate=certificate_candidate,
                    certificate_flat_rounds=certificate_flat_rounds,
                    certificate_no_column_rounds=certificate_no_column_rounds,
                    depth=0,
                    completion_bound_phase="after_retry",
                )
                final_completion_bound_eligible = bool(
                    config.get("journey_certificate_completion_bound_after_retry_enabled", False)
                ) and bool(final_probe_config.direct_journey_label_completion_bound_enabled)
                final_probe_viable, _final_probe_budget = _journey_completion_bound_probe_budget_is_viable(
                    config,
                    remaining=retry_remaining,
                    min_pricing_time=min_pricing_time,
                )
                if bool(final_completion_bound_eligible) and bool(final_probe_viable):
                    skip_ordinary_retry_for_final_probe = True
                    skip_reason = "weak_negative_filtered_goes_to_final_probe"
            if bool(skip_ordinary_retry_for_final_probe):
                retry_enabled = False
                logger.log(
                    "journey_exact_pricing_retry_skipped",
                    node_id=0,
                    depth=0,
                    cg_iter=cg_iter,
                    previous_status=pricing.status,
                    previous_reason=pricing.reason,
                    reason=skip_reason or "ordinary_retry_skipped_for_final_probe",
                    certificate_no_column_rounds=certificate_no_column_rounds,
                )
            if retry_enabled and retry_remaining > max(min_pricing_time, retry_min_time):
                final_probe_config, _final_probe_mode = _journey_certificate_pricing_config(
                    config,
                    exact_pricing_config,
                    certificate_candidate=certificate_candidate,
                    certificate_flat_rounds=certificate_flat_rounds,
                    certificate_no_column_rounds=certificate_no_column_rounds,
                    depth=0,
                    completion_bound_phase="after_retry",
                )
                final_completion_bound_eligible = bool(
                    config.get("journey_certificate_completion_bound_after_retry_enabled", False)
                ) and bool(final_probe_config.direct_journey_label_completion_bound_enabled)
                retry_budget, completion_bound_final_reserve = _journey_retry_budget_with_completion_reserve(
                    config,
                    retry_remaining=retry_remaining,
                    min_pricing_time=min_pricing_time,
                    retry_min_time=retry_min_time,
                    final_completion_bound_eligible=final_completion_bound_eligible,
                )
                retry_config = replace(
                    exact_pricing_config,
                    time_limit=retry_budget,
                    profile_generation_time_fraction=float(
                        config.get("journey_retry_incomplete_no_column_generation_fraction", 1.0)
                    ),
                )
                retry_config, retry_force_ng = _journey_retry_force_ng_config(
                    config,
                    retry_config,
                    depth=0,
                    cg_iter=cg_iter,
                    certificate_candidate=certificate_candidate,
                    certificate_flat_rounds=certificate_flat_rounds,
                    retry_negative_after_no_column_rounds=certificate_no_column_rounds,
                    progress_classification=progress_classification,
                )
                logger.log(
                    "journey_exact_pricing_retry",
                    node_id=0,
                    cg_iter=cg_iter,
                    remaining=round(float(retry_remaining), 6),
                    previous_status=pricing.status,
                    previous_reason=pricing.reason,
                    previous_best_reduced_cost=None
                    if pricing.best_reduced_cost is None
                    else round(float(pricing.best_reduced_cost), 9),
                    certificate_no_column_rounds=certificate_no_column_rounds,
                    completion_bound_enabled=bool(retry_config.direct_journey_label_completion_bound_enabled),
                    direct_journey_label_pricing_enabled=bool(retry_config.direct_journey_label_pricing_enabled),
                    direct_journey_label_ng_dssr_enabled=bool(retry_config.direct_journey_label_ng_dssr_enabled),
                    retry_force_ng=bool(retry_force_ng),
                    completion_bound_final_reserve=round(float(completion_bound_final_reserve), 6),
                )
                retry_pricing_duals, retry_pricing_dual_source = _journey_retry_duals_after_average_filter(
                    pricing,
                    solution.duals,
                    pricing_duals,
                    pricing_dual_source,
                )
                retry_pricing_kind = "exact_retry"
                retry_duals, retry_dual_source = _journey_exact_pricing_duals(
                    solution.duals,
                    retry_pricing_duals,
                    retry_pricing_dual_source,
                    learning_runtime=learning_runtime,
                    certificate_candidate=certificate_candidate,
                    completion_bound_enabled=retry_config.direct_journey_label_completion_bound_enabled,
                )
                retry_active_duals = retry_duals
                retry_active_dual_source = retry_dual_source
                pricing = price_journeys(
                    data,
                    retry_duals,
                    tuple(),
                    config=retry_config,
                    cuts=tuple(cuts),
                    trip_cache=trip_cache,
                    resource_cache=resource_cache,
                    forbidden_journey_signatures=_journey_forbidden_signatures_for_node(journey_pool, tuple()),
                    dominant_task_set_costs=_journey_pricing_dominant_task_set_costs(journey_pool, cuts, tuple()),
                    priority_task_sets=active_task_sets,
                    active_support_task_sets=active_task_sets,
                )
                if retry_dual_source == "dual_average":
                    pricing = _journey_dual_average_true_rc_filtered_pricing(
                        logger,
                        pricing,
                        runtime=dual_averaging_runtime,
                        true_duals=solution.duals,
                        cuts=tuple(cuts),
                        config=config,
                        cg_iter=cg_iter,
                        node_id=0,
                        depth=0,
                        pricing_kind="exact_retry",
                    )
                pricing_calls += 1
                exact_pricing_calls += 1
                generated_sequences += pricing.generated_sequences
                evaluated_timed_trips += pricing.evaluated_timed_trips
                _log_journey_pricing(
                    logger,
                    pricing,
                    cg_iter,
                    pricing_kind="exact_retry",
                    config=retry_config,
                    pricing_dual_source=retry_dual_source,
                )
                if _journey_completion_bound_final_probe_needed(config, pricing):
                    final_remaining = max(0.0, time_limit - (time.perf_counter() - started))
                    final_min_time = float(
                        config.get("journey_certificate_completion_bound_after_retry_min_time", retry_min_time)
                    )
                    final_probe_viable, final_probe_budget = _journey_completion_bound_probe_budget_is_viable(
                        config,
                        remaining=final_remaining,
                        min_pricing_time=min_pricing_time,
                    )
                    if final_probe_viable:
                        dominant_task_set_costs = _journey_pricing_dominant_task_set_costs(
                            journey_pool,
                            cuts,
                            tuple(),
                        )
                        patrol_config, patrol_mode = _journey_hidden_negative_patrol_config(
                            config,
                            retry_config,
                            remaining=final_remaining,
                            min_pricing_time=min_pricing_time,
                            depth=0,
                            cg_iter=cg_iter,
                            certificate_candidate=certificate_candidate,
                            certificate_flat_rounds=certificate_flat_rounds,
                            retry_negative_after_no_column_rounds=certificate_no_column_rounds,
                            progress_classification=progress_classification,
                        )
                        if patrol_mode:
                            logger.log(
                                "journey_hidden_negative_patrol_after_retry",
                                node_id=0,
                                depth=0,
                                cg_iter=cg_iter,
                                remaining=round(float(final_remaining), 6),
                                previous_status=pricing.status,
                                previous_reason=pricing.reason,
                                patrol_mode=patrol_mode,
                                direct_journey_label_pricing_enabled=True,
                                completion_bound_enabled=False,
                                certificate_capable=False,
                            )
                            patrol_duals, patrol_dual_source = _journey_hidden_negative_patrol_duals(
                                config,
                                patrol_mode,
                                scip_duals=solution.duals,
                                pricing_duals=pricing_duals,
                                pricing_dual_source=pricing_dual_source,
                                default_source="scip_hidden_negative_patrol_after_retry",
                            )
                            patrol_pricing = price_journeys(
                                data,
                                patrol_duals,
                                tuple(),
                                config=patrol_config,
                                cuts=tuple(cuts),
                                trip_cache=trip_cache,
                                resource_cache=resource_cache,
                                forbidden_journey_signatures=_journey_forbidden_signatures_for_node(
                                    journey_pool, tuple()
                                ),
                                dominant_task_set_costs=dominant_task_set_costs,
                            )
                            pricing_calls += 1
                            exact_pricing_calls += 1
                            generated_sequences += patrol_pricing.generated_sequences
                            evaluated_timed_trips += patrol_pricing.evaluated_timed_trips
                            _log_journey_pricing(
                                logger,
                                patrol_pricing,
                                cg_iter,
                                pricing_kind="exact_hidden_negative_patrol_after_retry",
                                config=patrol_config,
                                pricing_dual_source=patrol_dual_source,
                            )
                            _log_hidden_negative_audit(
                                logger,
                                data,
                                journey_pool,
                                pricing,
                                patrol_pricing,
                                patrol_duals,
                                tuple(cuts),
                                tuple(),
                                cg_iter,
                                hidden_pricing_kind="exact_hidden_negative_patrol_after_retry",
                                hidden_dual_source=patrol_dual_source,
                                max_logged_journeys=int(
                                    config.get("journey_hidden_negative_audit_max_logged_journeys", 8)
                                ),
                                trigger="hidden_negative_patrol_after_retry",
                            )
                            pricing = patrol_pricing
                            retry_active_duals = patrol_duals
                            retry_active_dual_source = patrol_dual_source
                            if patrol_pricing.journeys:
                                patrol_new_task_sets = int(
                                    getattr(
                                        patrol_pricing,
                                        "direct_label_harvest_selected_new_task_set_count",
                                        getattr(patrol_pricing, "harvest_selected_new_task_set_count", 0),
                                    )
                                )
                                replacement_only_escalates = bool(
                                    config.get("journey_hidden_negative_patrol_replacement_only_escalates_to_cb", False)
                                )
                                if (
                                    replacement_only_escalates
                                    and bool(certificate_candidate)
                                    and patrol_new_task_sets <= 0
                                ):
                                    logger.log(
                                        "journey_hidden_negative_patrol_replacement_only_escalation",
                                        node_id=0,
                                        depth=0,
                                        cg_iter=cg_iter,
                                        negative_journeys=len(patrol_pricing.journeys),
                                        selected_new_task_sets=patrol_new_task_sets,
                                        selected_replacement_task_sets=int(
                                            getattr(
                                                patrol_pricing,
                                                "direct_label_harvest_selected_replacement_task_set_count",
                                                getattr(
                                                    patrol_pricing,
                                                    "harvest_selected_replacement_task_set_count",
                                                    0,
                                                ),
                                            )
                                        ),
                                        next_oracle="exact_completion_bound_retry",
                                        exact_safe=True,
                                        certificate_capable=False,
                                    )
                                else:
                                    _seed_hidden_negative_profile_catalog(
                                        logger,
                                        data,
                                        config,
                                        patrol_pricing,
                                        patrol_duals,
                                        retry_config,
                                        trip_cache,
                                        tuple(),
                                        cg_iter,
                                        pricing_kind="exact_hidden_negative_patrol_after_retry",
                                        node_id=0,
                                        depth=0,
                                    )
                                    _log_journey_gat_target_mode_shadow(
                                        logger,
                                        patrol_pricing.journeys,
                                        solution.duals,
                                        tuple(cuts),
                                        config,
                                        cg_iter=cg_iter,
                                        node_id=0,
                                        depth=0,
                                        pricing_kind="exact_hidden_negative_patrol_after_retry",
                                        certificate_candidate=certificate_candidate,
                                    )
                                    added = _add_priced_journeys(journey_pool, patrol_pricing.journeys)
                                    _log_journey_addition(
                                        logger,
                                        patrol_pricing,
                                        added,
                                        cg_iter,
                                        pricing_kind="exact_hidden_negative_patrol_after_retry",
                                        active_task_sets=active_task_sets,
                                    )
                                    if added > 0:
                                        certificate_no_column_rounds = 0
                                        recent_priced_journeys = list(patrol_pricing.journeys)
                                        recent_changed_task_sets = list(
                                            getattr(added, "changed_task_sets", tuple())
                                        )
                                        continue
                        sweep_enabled, sweep_mode = _journey_new_task_set_sweep_enabled(
                            config,
                            remaining=final_remaining,
                            min_pricing_time=min_pricing_time,
                            depth=0,
                        )
                        if sweep_enabled:
                            logger.log(
                                "journey_new_task_set_sweep",
                                node_id=0,
                                depth=0,
                                cg_iter=cg_iter,
                                remaining=round(float(final_remaining), 6),
                                previous_status=pricing.status,
                                previous_reason=pricing.reason,
                                sweep_mode=sweep_mode,
                                known_task_sets=len(dominant_task_set_costs),
                                certificate_capable=False,
                            )
                            sweep_duals = solution.duals
                            sweep_dual_source = "scip_new_task_set_sweep"
                            sweep_pricing = _price_new_task_set_sweep(
                                data,
                                sweep_duals,
                                tuple(cuts),
                                journey_pool,
                                config,
                                time_limit=float(sweep_mode.get("time_limit", 0.0)),
                                forbidden_journey_signatures=_journey_forbidden_signatures_for_node(
                                    journey_pool, tuple()
                                ),
                            )
                            pricing_calls += 1
                            exact_pricing_calls += 1
                            generated_sequences += sweep_pricing.generated_sequences
                            evaluated_timed_trips += sweep_pricing.evaluated_timed_trips
                            _log_journey_pricing(
                                logger,
                                sweep_pricing,
                                cg_iter,
                                pricing_kind="exact_new_task_set_sweep",
                                config=retry_config,
                                pricing_dual_source=sweep_dual_source,
                            )
                            if sweep_pricing.journeys:
                                _log_hidden_negative_audit(
                                    logger,
                                    data,
                                    journey_pool,
                                    pricing,
                                    sweep_pricing,
                                    sweep_duals,
                                    tuple(cuts),
                                    tuple(),
                                    cg_iter,
                                    hidden_pricing_kind="exact_new_task_set_sweep",
                                    hidden_dual_source=sweep_dual_source,
                                    max_logged_journeys=int(
                                        config.get("journey_hidden_negative_audit_max_logged_journeys", 8)
                                    ),
                                    trigger="new_task_set_sweep_after_retry",
                                )
                                _log_journey_gat_target_mode_shadow(
                                    logger,
                                    sweep_pricing.journeys,
                                    solution.duals,
                                    tuple(cuts),
                                    config,
                                    cg_iter=cg_iter,
                                    node_id=0,
                                    depth=0,
                                    pricing_kind="exact_new_task_set_sweep",
                                    certificate_candidate=certificate_candidate,
                                )
                                added = _add_priced_journeys(journey_pool, sweep_pricing.journeys)
                                _log_journey_addition(
                                    logger,
                                    sweep_pricing,
                                    added,
                                    cg_iter,
                                    pricing_kind="exact_new_task_set_sweep",
                                    active_task_sets=active_task_sets,
                                )
                                if added > 0:
                                    certificate_no_column_rounds = 0
                                    recent_priced_journeys = list(sweep_pricing.journeys)
                                    recent_changed_task_sets = list(
                                        getattr(added, "changed_task_sets", tuple())
                                    )
                                    continue
                        fixed_targets = _journey_fixed_task_set_repair_target_task_sets(
                            config,
                            recent_changed_task_sets=recent_changed_task_sets,
                            active_task_sets=active_task_sets,
                        )
                        if not fixed_targets:
                            fixed_targets = _journey_fixed_task_set_repair_pool_targets(
                                config,
                                journey_pool,
                                solution.duals,
                                tuple(cuts),
                            )
                        fixed_enabled, fixed_mode = _journey_fixed_task_set_repair_enabled(
                            config,
                            remaining=final_remaining,
                            min_pricing_time=min_pricing_time,
                            depth=0,
                            target_task_sets=fixed_targets,
                        )
                        if fixed_enabled and dominant_task_set_costs:
                            logger.log(
                                "journey_fixed_task_set_repair",
                                node_id=0,
                                depth=0,
                                cg_iter=cg_iter,
                                remaining=round(float(final_remaining), 6),
                                previous_status=pricing.status,
                                previous_reason=pricing.reason,
                                repair_mode=fixed_mode,
                                known_task_sets=len(dominant_task_set_costs),
                                certificate_capable=False,
                            )
                            fixed_duals = solution.duals
                            fixed_dual_source = "scip_fixed_task_set_repair"
                            fixed_pricing = _price_fixed_task_set_representatives(
                                data,
                                fixed_duals,
                                tuple(cuts),
                                journey_pool,
                                fixed_targets,
                                config,
                                time_limit=float(fixed_mode.get("time_limit", 0.0)),
                                forbidden_journey_signatures=_journey_forbidden_signatures_for_node(
                                    journey_pool, tuple()
                                ),
                            )
                            pricing_calls += 1
                            exact_pricing_calls += 1
                            generated_sequences += fixed_pricing.generated_sequences
