def _journey_pricing_oracle_classification(pricing: Any) -> str:
    state = _journey_pricing_state(pricing)
    if state == PRICING_STATE_FOUND_NEGATIVE:
        return "negative_column_found"
    reason = str(getattr(pricing, "reason", ""))
    if state == PRICING_STATE_CERTIFIED_NO_NEGATIVE:
        return "global_certificate"
    if state == PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED:
        return "oracle_exhausted_local_universe"
    if state == PRICING_STATE_DUPLICATE_ONLY:
        return "duplicate_tail"
    if bool(getattr(pricing, "duplicate_scan_limited", False)):
        return "duplicate_scan_limited"
    if int(getattr(pricing, "weak_negative_journeys_filtered", 0)) > 0:
        return "weak_negative_filtered_incomplete"
    if "time" in reason:
        return "pricing_time_incomplete"
    return "pricing_incomplete"


def _journey_pricing_state(pricing: Any) -> str:
    state = str(getattr(pricing, "pricing_state", "") or "")
    if state in {
        PRICING_STATE_FOUND_NEGATIVE,
        PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED,
        PRICING_STATE_CERTIFIED_NO_NEGATIVE,
        PRICING_STATE_INCOMPLETE_LIMIT,
        PRICING_STATE_DUPLICATE_ONLY,
    }:
        if state == PRICING_STATE_CERTIFIED_NO_NEGATIVE and not (
            bool(getattr(pricing, "global_certificate_capable", False))
            and str(getattr(pricing, "status", "")) == "OPTIMAL"
            and not bool(getattr(pricing, "journeys", None))
            and _journey_pricing_certificate_reason_allowed(pricing)
        ):
            if (
                bool(getattr(pricing, "exhausted", False))
                and str(getattr(pricing, "status", "")) == "OPTIMAL"
            ):
                return PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED
            return PRICING_STATE_INCOMPLETE_LIMIT
        return state
    if getattr(pricing, "journeys", None):
        return PRICING_STATE_FOUND_NEGATIVE
    reason = str(getattr(pricing, "reason", ""))
    if (
        bool(getattr(pricing, "exhausted", False))
        and not bool(getattr(pricing, "journeys", None))
        and bool(getattr(pricing, "global_certificate_capable", False))
        and str(getattr(pricing, "status", "")) == "OPTIMAL"
        and _journey_pricing_certificate_reason_allowed(pricing)
    ):
        return PRICING_STATE_CERTIFIED_NO_NEGATIVE
    if (not bool(getattr(pricing, "exhausted", False))) or str(getattr(pricing, "status", "")) != "OPTIMAL":
        return PRICING_STATE_INCOMPLETE_LIMIT
    if (
        bool(getattr(pricing, "duplicate_scan_limited", False))
        or int(getattr(pricing, "duplicate_candidates_filtered", 0)) > 0
        or int(getattr(pricing, "existing_journeys_filtered", 0)) > 0
        or int(getattr(pricing, "dominated_task_set_journeys_filtered", 0)) > 0
        or reason == "negative_journeys_already_in_pool"
    ):
        return PRICING_STATE_DUPLICATE_ONLY
    if bool(getattr(pricing, "exhausted", False)) and str(getattr(pricing, "status", "")) == "OPTIMAL":
        return PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED
    return PRICING_STATE_INCOMPLETE_LIMIT


def _journey_pricing_certificate_reason_allowed(pricing: Any) -> bool:
    reason = str(getattr(pricing, "reason", ""))
    if bool(getattr(pricing, "completion_bound_enabled", False)) and reason == "direct_label_no_negative_journey":
        return True
    if (
        str(getattr(pricing, "final_judge_engine", "")) in {"sharded_pulse", "sharded_pulse_dummy"}
        and bool(getattr(pricing, "final_judge_certificate_capable", False))
        and reason == "sharded_pulse_no_negative_journey"
    ):
        return True
    if bool(getattr(pricing, "ng_certificate_from_relaxation", False)) and reason == "ng_dssr_relaxed_no_negative_journey":
        if bool(getattr(pricing, "ng_certificate_limit_hit", False)):
            return False
        if bool(getattr(pricing, "ng_probe_limit_hit", False)):
            return False
        if getattr(pricing, "ng_relaxation_superset", None) is not True:
            return False
        return True
    return False


def _journey_pricing_is_global_certificate(pricing: Any) -> bool:
    """Return whether a pricing result proves no journey column exists.

    ``exhausted=True`` is oracle-local.  Profile/streaming or NG workers may
    exhaust their own relaxed/generated universe, but that is not a journey
    master certificate.  Global certificates are explicit final-judge no-column
    proofs: the legacy true-dual direct-label completion-bound judge, or the
    sharded Pulse final judge when its ledger is certificate-capable.
    """

    return _journey_pricing_state(pricing) == PRICING_STATE_CERTIFIED_NO_NEGATIVE


def _journey_pricing_certificate_rejection_reason(pricing: Any) -> str:
    if not bool(getattr(pricing, "exhausted", False)):
        return str(getattr(pricing, "reason", "") or "pricing_incomplete")
    if getattr(pricing, "journeys", None):
        return "negative_journey_requires_column_addition"
    if str(getattr(pricing, "final_judge_engine", "")) in {"sharded_pulse", "sharded_pulse_dummy"}:
        if not bool(getattr(pricing, "global_certificate_capable", False)):
            return "sharded_pulse_requires_global_certificate_capable"
        if not bool(getattr(pricing, "final_judge_certificate_capable", False)):
            return "sharded_pulse_requires_certificate_capable_final_judge"
        if (
            str(getattr(pricing, "status", "")) != "OPTIMAL"
            or str(getattr(pricing, "reason", "")) != "sharded_pulse_no_negative_journey"
        ):
            return "sharded_pulse_final_judge_not_no_column_certificate"
        return "pricing_certificate_rejected"
    if not bool(getattr(pricing, "completion_bound_enabled", False)):
        return "profile_exhausted_requires_direct_label_final_judge"
    if not bool(getattr(pricing, "global_certificate_capable", False)):
        return "completion_bound_worker_requires_direct_label_final_judge"
    if str(getattr(pricing, "reason", "")) != "direct_label_no_negative_journey":
        return "direct_label_final_judge_not_no_column_certificate"
    return "pricing_certificate_rejected"


def _journey_duplicate_only_final_judge_can_certify(
    data: FutureData,
    config: dict[str, Any],
    journey_pool: JourneyPool,
    branch_constraints: tuple[BranchConstraint, ...],
    cuts: tuple[FutureCut, ...],
    fleet_limit: int | None,
    pricing: Any,
    logger: FutureLogger,
    cg_iter: int,
    *,
    node_id: int = 0,
    depth: int = 0,
) -> bool:
    """Return False because DUPLICATE_ONLY is never certificate evidence."""

    if _journey_pricing_state(pricing) == PRICING_STATE_DUPLICATE_ONLY:
        logger.log(
            "journey_duplicate_only_certificate_audit",
            node_id=int(node_id),
            depth=int(depth),
            cg_iter=int(cg_iter),
            accepted=False,
            reason="duplicate_only_promotion_disabled",
            pricing_reason=str(getattr(pricing, "reason", "")),
            exact_safe=True,
        )
    return False


def _journey_promote_duplicate_only_final_judge_certificate(
    data: FutureData,
    config: dict[str, Any],
    journey_pool: JourneyPool,
    branch_constraints: tuple[BranchConstraint, ...],
    cuts: tuple[FutureCut, ...],
    fleet_limit: int | None,
    pricing: Any,
    logger: FutureLogger,
    cg_iter: int,
    *,
    node_id: int = 0,
    depth: int = 0,
) -> Any:
    _journey_duplicate_only_final_judge_can_certify(
        data,
        config,
        journey_pool,
        branch_constraints,
        cuts,
        fleet_limit,
        pricing,
        logger,
        cg_iter,
        node_id=node_id,
        depth=depth,
    )
    return pricing


def _journey_sharded_pulse_audit_category(pricing: Any) -> str:
    state = _journey_pricing_state(pricing)
    if state == PRICING_STATE_CERTIFIED_NO_NEGATIVE:
        return "certified"
    if state == PRICING_STATE_FOUND_NEGATIVE:
        return "found_negative"
    if state == PRICING_STATE_DUPLICATE_ONLY:
        return "duplicate_only"
    if state == PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED:
        return "local_no_column_uncertified"
    return "incomplete"


def _journey_sharded_pulse_audit_disagreement_type(
    legacy_pricing: Any,
    pulse_pricing: Any,
) -> str:
    comparison = _journey_sharded_pulse_audit_comparison_type(legacy_pricing, pulse_pricing)
    legacy = _journey_sharded_pulse_audit_matrix_state(legacy_pricing)
    pulse = _journey_sharded_pulse_audit_matrix_state(pulse_pricing)
    return "" if legacy == pulse else comparison


def _journey_sharded_pulse_audit_matrix_state(pricing: Any) -> str:
    category = _journey_sharded_pulse_audit_category(pricing)
    if category == "certified":
        return "certified"
    if category == "found_negative":
        return "negative"
    return "incomplete"


def _journey_sharded_pulse_audit_comparison_type(
    legacy_pricing: Any,
    pulse_pricing: Any,
) -> str:
    legacy = _journey_sharded_pulse_audit_matrix_state(legacy_pricing)
    pulse = _journey_sharded_pulse_audit_matrix_state(pulse_pricing)
    return f"legacy_{legacy}_pulse_{pulse}"


def _journey_sharded_pulse_audit_disagreement_severity(disagreement_type: str) -> str:
    if disagreement_type in {
        "legacy_certified_pulse_negative",
        "legacy_negative_pulse_certified",
    }:
        return "critical"
    if disagreement_type:
        return "warning"
    return "info"


def _journey_sharded_pulse_audit_status(pricing: Any) -> str:
    category = _journey_sharded_pulse_audit_category(pricing)
    if category == "certified":
        return PRICING_STATE_CERTIFIED_NO_NEGATIVE
    if category == "found_negative":
        return PRICING_STATE_FOUND_NEGATIVE
    if category == "duplicate_only":
        return PRICING_STATE_DUPLICATE_ONLY
    if category == "local_no_column_uncertified":
        return PRICING_STATE_LOCAL_NO_COLUMN_UNCERTIFIED
    return "AUDIT_INCOMPLETE"


def _journey_sharded_pulse_audit_payload(
    legacy_pricing: Any,
    pulse_pricing: Any,
    *,
    elapsed: float,
    enabled: bool = True,
    context_hashes: dict[str, str] | None = None,
) -> dict[str, Any]:
    disagreement = _journey_sharded_pulse_audit_disagreement_type(legacy_pricing, pulse_pricing)
    legacy_category = _journey_sharded_pulse_audit_category(legacy_pricing)
    pulse_category = _journey_sharded_pulse_audit_category(pulse_pricing)
    hashes = context_hashes or {}
    payload = {
        "pulse_audit_enabled": bool(enabled),
        "pulse_audit_status": _journey_sharded_pulse_audit_status(pulse_pricing),
        "pulse_audit_reason": str(getattr(pulse_pricing, "reason", "")),
        "pulse_audit_global_certificate_capable": bool(
            _journey_pricing_is_global_certificate(pulse_pricing)
        ),
        "pulse_audit_agrees_with_legacy": bool(
            legacy_category == pulse_category and disagreement == ""
        ),
        "pulse_audit_comparison_type": _journey_sharded_pulse_audit_comparison_type(
            legacy_pricing, pulse_pricing
        ),
        "pulse_audit_disagreement_type": disagreement,
        "pulse_audit_disagreement_severity": _journey_sharded_pulse_audit_disagreement_severity(
            disagreement
        ),
        "pulse_audit_legacy_state": _journey_pricing_state(legacy_pricing),
        "pulse_audit_legacy_best_rc": None
        if getattr(legacy_pricing, "best_reduced_cost", None) is None
        else round(float(getattr(legacy_pricing, "best_reduced_cost")), 9),
        "pulse_audit_pulse_best_rc": None
        if getattr(pulse_pricing, "best_reduced_cost", None) is None
        else round(float(getattr(pulse_pricing, "best_reduced_cost")), 9),
        "pulse_audit_time": round(float(elapsed), 9),
        "pulse_audit_recursions": int(getattr(pulse_pricing, "pulse_recursions", 0)),
        "pulse_audit_shards_total": int(getattr(pulse_pricing, "final_judge_shards_total", 0)),
        "pulse_audit_shards_certified": int(
            getattr(pulse_pricing, "final_judge_shards_certified", 0)
        ),
        "pulse_audit_shards_incomplete": int(
            getattr(pulse_pricing, "final_judge_shards_incomplete", 0)
        ),
        "pulse_audit_shards_negative": int(
            getattr(pulse_pricing, "final_judge_shards_negative_found", 0)
        ),
        "pulse_audit_shards_refined": int(
            getattr(pulse_pricing, "final_judge_shards_refined", 0)
        ),
        "pulse_audit_low_roi_shards": int(getattr(pulse_pricing, "pulse_low_roi_shards", 0)),
        "pulse_audit_bound_pruned": int(getattr(pulse_pricing, "pulse_bound_pruned", 0)),
        "pulse_audit_archive_pruned": int(getattr(pulse_pricing, "pulse_archive_pruned", 0)),
        "pulse_audit_time_window_pruned": int(
            getattr(pulse_pricing, "transition_time_window_pruned", 0)
        ),
        "pulse_audit_return_pruned": int(getattr(pulse_pricing, "transition_return_pruned", 0)),
        "pulse_audit_harvested_count": int(getattr(pulse_pricing, "pulse_harvested_count", 0)),
    }
    payload.update(
        {
            "pulse_audit_context_hash": str(hashes.get("context", "")),
            "pulse_audit_true_dual_hash": str(hashes.get("true_dual", "")),
            "pulse_audit_cut_hash": str(hashes.get("cuts", "")),
            "pulse_audit_branch_hash": str(hashes.get("branch", "")),
            "pulse_audit_forbidden_signature_hash": str(hashes.get("forbidden", "")),
        }
    )
    return payload


def _journey_sharded_pulse_audit_payload_has_negative_signal(payload: dict[str, Any]) -> bool:
    if str(payload.get("pulse_audit_status", "")) == PRICING_STATE_FOUND_NEGATIVE:
        return True
    if str(payload.get("pulse_audit_comparison_type", "")) in {
        "legacy_incomplete_pulse_negative",
        "legacy_negative_pulse_negative",
    }:
        return True
    return _journey_sharded_pulse_audit_payload_int(payload, "pulse_audit_shards_negative") > 0


def _journey_sharded_pulse_audit_payload_int(
    payload: dict[str, Any],
    key: str,
    *,
    default: int = 0,
) -> int:
    try:
        return int(payload.get(key, default) or default)
    except (TypeError, ValueError):
        return int(default)


def _journey_sharded_pulse_audit_signal_from_payload(
    payload: dict[str, Any],
    *,
    node_id: int,
    depth: int,
    cg_iter: int,
) -> dict[str, Any] | None:
    if not _journey_sharded_pulse_audit_payload_has_negative_signal(payload):
        return None
    return {
        "node_id": int(node_id),
        "depth": int(depth),
        "cg_iter": int(cg_iter),
        "context_hashes": {
            "context": str(payload.get("pulse_audit_context_hash", "")),
            "true_dual": str(payload.get("pulse_audit_true_dual_hash", "")),
            "cuts": str(payload.get("pulse_audit_cut_hash", "")),
            "branch": str(payload.get("pulse_audit_branch_hash", "")),
            "forbidden": str(payload.get("pulse_audit_forbidden_signature_hash", "")),
        },
        "comparison_type": str(payload.get("pulse_audit_comparison_type", "")),
        "shards_negative": _journey_sharded_pulse_audit_payload_int(
            payload, "pulse_audit_shards_negative"
        ),
        "harvested_count": _journey_sharded_pulse_audit_payload_int(
            payload, "pulse_audit_harvested_count"
        ),
        "best_rc": payload.get("pulse_audit_pulse_best_rc"),
    }


def _journey_sharded_pulse_audit_signal_valid_for_worker(
    signal: dict[str, Any] | None,
    *,
    node_id: int,
    depth: int,
    cg_iter: int,
    max_age: int,
) -> bool:
    if not signal:
        return False
    if int(signal.get("node_id", -1)) != int(node_id):
        return False
    if int(signal.get("depth", -1)) != int(depth):
        return False
    signal_iter = int(signal.get("cg_iter", -10**9))
    return 0 < int(cg_iter) - signal_iter <= max(1, int(max_age))


def _journey_sharded_pulse_current_probe_hard_tail_fingerprint_allows(
    config: dict[str, Any],
    *,
    certificate_flat_rounds: int,
    certificate_no_column_rounds: int,
) -> bool:
    if not bool(config.get("journey_sharded_pulse_worker_current_probe_hard_tail_fingerprint_enabled", False)):
        return True
    min_flat = max(
        0,
        int(config.get("journey_sharded_pulse_worker_current_probe_min_certificate_flat_rounds", 1)),
    )
    min_no_column = max(
        0,
        int(config.get("journey_sharded_pulse_worker_current_probe_min_no_column_rounds", 1)),
    )
    flat_ok = min_flat <= 0 or int(certificate_flat_rounds) >= min_flat
    no_column_ok = min_no_column <= 0 or int(certificate_no_column_rounds) >= min_no_column
    return bool(flat_ok or no_column_ok)


def _journey_sharded_pulse_worker_success_cooldown_rounds(
    config: dict[str, Any],
    added: Any,
    *,
    active_task_sets: set[frozenset[int]] | frozenset[frozenset[int]] | None = None,
) -> int:
    base_cooldown = max(
        0,
        int(config.get("journey_sharded_pulse_hidden_negative_worker_success_cooldown_rounds", 0)),
    )
    if not bool(
        config.get(
            "journey_sharded_pulse_hidden_negative_worker_continue_only_on_active_support",
            False,
        )
    ):
        return base_cooldown
    inactive_cooldown = max(
        base_cooldown,
        max(
            0,
            int(
                config.get(
                    "journey_sharded_pulse_hidden_negative_worker_inactive_success_cooldown_rounds",
                    base_cooldown,
                )
            ),
        ),
    )
    if int(added) <= 0:
        return base_cooldown
    changed = {
        frozenset(int(task) for task in task_set)
        for task_set in getattr(added, "changed_task_sets", tuple())
    }
    if not changed or active_task_sets is None:
        return inactive_cooldown
    active = {frozenset(int(task) for task in task_set) for task_set in active_task_sets}
    if changed.intersection(active):
        return base_cooldown
    return inactive_cooldown


def _journey_sharded_pulse_worker_failure_cooldown_rounds(
    config: dict[str, Any],
    pricing: Any,
    *,
    added: Any | None = None,
) -> int:
    cooldown = max(
        0,
        int(config.get("journey_sharded_pulse_hidden_negative_worker_failure_cooldown_rounds", 0)),
    )
    if cooldown <= 0:
        return 0
    if added is not None:
        return 0 if int(added) > 0 else cooldown
    if list(getattr(pricing, "journeys", []) or []):
        return 0
    return cooldown


