def _log_journey_sharded_pulse_audit_skipped(
    logger: FutureLogger,
    config: dict[str, Any],
    *,
    skip_reason: str,
    trigger: str,
    cg_iter: int,
    node_id: int = 0,
    depth: int = 0,
) -> None:
    if not bool(config.get("journey_sharded_pulse_audit_log_skips", False)):
        return
    logger.log(
        "journey_sharded_pulse_audit",
        node_id=int(node_id),
        depth=int(depth),
        cg_iter=int(cg_iter),
        pulse_audit_enabled=bool(config.get("journey_sharded_pulse_audit_enabled", False)),
        pulse_audit_skipped=True,
        pulse_audit_skip_reason=str(skip_reason),
        pulse_audit_trigger=str(trigger),
        pulse_audit_allow_certificate_effect=bool(
            config.get("journey_sharded_pulse_audit_allow_certificate_effect", False)
        ),
    )


def _log_journey_sharded_pulse_worker_skipped(
    logger: FutureLogger,
    config: dict[str, Any],
    *,
    skip_reason: str,
    trigger: str,
    cg_iter: int,
    node_id: int = 0,
    depth: int = 0,
    context_hashes: dict[str, str] | None = None,
    signal_source: str = "none",
    previous_audit_signal: bool = False,
    current_probe_signal: bool = False,
) -> None:
    if not bool(config.get("journey_sharded_pulse_hidden_negative_worker_log_skips", False)):
        return
    hashes = context_hashes or {}
    logger.log(
        "journey_sharded_pulse_hidden_negative_worker",
        node_id=int(node_id),
        depth=int(depth),
        cg_iter=int(cg_iter),
        pulse_worker_enabled=bool(
            config.get("journey_sharded_pulse_hidden_negative_worker_enabled", False)
        ),
        pulse_worker_skipped=True,
        pulse_worker_skip_reason=str(skip_reason),
        pulse_worker_trigger=str(trigger),
        pulse_worker_signal_source=str(signal_source),
        pulse_worker_previous_audit_signal=bool(previous_audit_signal),
        pulse_worker_current_probe_signal=bool(current_probe_signal),
        pulse_worker_allow_certificate_effect=False,
        pulse_worker_status="SKIPPED",
        pulse_worker_returned_journeys=0,
        pulse_worker_context_hash=str(hashes.get("context", "")),
        pulse_worker_true_dual_hash=str(hashes.get("true_dual", "")),
        pulse_worker_cut_hash=str(hashes.get("cuts", "")),
        pulse_worker_branch_hash=str(hashes.get("branch", "")),
        pulse_worker_forbidden_signature_hash=str(hashes.get("forbidden", "")),
    )


def _journey_sharded_pulse_audit_trigger_allows(
    config: dict[str, Any],
    *,
    trigger: str,
    depth: int,
) -> tuple[bool, str]:
    if not bool(config.get("journey_sharded_pulse_audit_enabled", False)):
        return False, "audit_disabled"
    configured = str(
        config.get("journey_sharded_pulse_audit_trigger", "after_legacy_final_judge") or ""
    ).strip().lower()
    current = str(trigger or "").strip().lower()
    if configured == "after_each_final_pricing":
        return True, ""
    if configured == current:
        return True, ""
    if bool(config.get("journey_sharded_pulse_audit_force_on_root", False)) and int(depth) <= 0:
        return True, ""
    if configured == "after_legacy_final_judge":
        return False, "not_after_legacy_final_judge"
    if configured == "on_certificate_candidate":
        return False, "pricing_state_not_eligible"
    return False, f"trigger_mismatch:{configured or 'unset'}"


def _journey_sharded_pulse_hidden_negative_worker_sanitize(
    pricing: JourneyPricingResult,
    duals: JourneyDuals,
    cuts: tuple[FutureCut, ...],
    *,
    eps: float,
) -> tuple[JourneyPricingResult, int]:
    if _journey_pricing_is_global_certificate(pricing):
        return (
            replace(
                pricing,
                journeys=[],
                exhausted=False,
                status="INCOMPLETE",
                reason="sharded_pulse_hidden_negative_worker_no_negative_not_certificate",
                global_certificate_capable=False,
                final_judge_certificate_capable=False,
                pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
                final_judge_incomplete_reason="worker_no_negative_not_certificate",
                pulse_negative_found=False,
            ),
            0,
        )
    kept: list[Any] = []
    filtered = 0
    best_rc = getattr(pricing, "best_reduced_cost", None)
    candidate_journeys = list(getattr(pricing, "journeys", []) or [])
    if not candidate_journeys and _journey_pricing_state(pricing) == PRICING_STATE_FOUND_NEGATIVE:
        return (
            replace(
                pricing,
                journeys=[],
                exhausted=False,
                selected_trips=0,
                status="INCOMPLETE",
                reason="sharded_pulse_hidden_negative_worker_empty_negative_result",
                global_certificate_capable=False,
                final_judge_certificate_capable=False,
                pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
                final_judge_incomplete_reason="empty_negative_result",
                pulse_negative_found=False,
            ),
            0,
        )
    for journey in candidate_journeys:
        true_rc = float(manual_journey_reduced_cost(journey, duals, cuts=cuts))
        best_rc = true_rc if best_rc is None else min(float(best_rc), true_rc)
        if true_rc < -float(eps):
            kept.append(journey)
        else:
            filtered += 1
    if len(kept) == len(candidate_journeys):
        return pricing, int(filtered)
    if kept:
        return (
            replace(
                pricing,
                journeys=kept,
                best_reduced_cost=best_rc,
                selected_trips=len(kept),
                status="FOUND_NEGATIVE",
                reason=str(getattr(pricing, "reason", "")) or "sharded_pulse_found_negative",
                global_certificate_capable=False,
                final_judge_certificate_capable=False,
                pricing_state=PRICING_STATE_FOUND_NEGATIVE,
                pulse_negative_found=True,
            ),
            int(filtered),
        )
    return (
        replace(
            pricing,
            journeys=[],
            exhausted=False,
            best_reduced_cost=best_rc,
            selected_trips=0,
            status="INCOMPLETE",
            reason="sharded_pulse_hidden_negative_worker_true_rc_filtered_empty",
            global_certificate_capable=False,
            final_judge_certificate_capable=False,
            pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
            final_judge_incomplete_reason="true_rc_filtered_empty",
            pulse_negative_found=False,
        ),
        int(filtered),
    )


def _journey_sharded_pulse_worker_impact_filtered(
    pricing: JourneyPricingResult,
    *,
    journey_pool: JourneyPool,
    active_task_sets: set[frozenset[int]] | frozenset[frozenset[int]] | None,
    duals: JourneyDuals,
    cuts: tuple[FutureCut, ...],
    mode: str,
    max_columns: int = 0,
    min_true_rc: float = 0.0,
) -> JourneyPricingResult:
    normalized_mode = str(mode or "off").strip().lower()
    journeys = list(getattr(pricing, "journeys", []) or [])
    threshold = float(min_true_rc)
    threshold_enabled = bool(threshold < 0.0)
    if normalized_mode == "off" or not journeys:
        _journey_sharded_pulse_worker_set_impact_attrs(
            pricing,
            enabled=normalized_mode != "off",
            mode=normalized_mode,
            candidate_count=len(journeys),
            selected_count=len(journeys),
            dropped_count=0,
            selected_new_task_set_count=0,
            selected_replacement_task_set_count=0,
            selected_active_support_changing_count=0,
            selected_weak_replacement_count=0,
            min_true_rc=threshold if threshold_enabled else None,
            selected_best_true_rc=None,
            rc_threshold_dropped_count=0,
        )
        return pricing

    active = (
        {frozenset(int(task) for task in task_set) for task_set in active_task_sets}
        if active_task_sets is not None
        else set()
    )
    ranked: list[tuple[tuple[int, float, int], Any, dict[str, Any]]] = []
    for index, journey in enumerate(journeys):
        task_key = frozenset(int(task) for task in getattr(journey, "task_set", frozenset()))
        incumbent = journey_pool.by_task_set.get(task_key)
        is_new_task_set = incumbent is None
        is_replacement = bool(
            incumbent is not None
            and float(getattr(journey, "cost", 0.0)) < float(getattr(incumbent, "cost", 0.0)) - 1.0e-9
        )
        is_active_support_changing = bool((is_new_task_set or is_replacement) and task_key in active)
        is_weak_replacement = bool((not is_new_task_set) and (not is_replacement))
        true_rc = float(manual_journey_reduced_cost(journey, duals, cuts=cuts))
        rank = (
            0 if is_active_support_changing else 1 if is_new_task_set else 2 if is_replacement else 3,
            true_rc,
            int(index),
        )
        ranked.append(
            (
                rank,
                journey,
                {
                    "new": is_new_task_set,
                    "replacement": is_replacement,
                    "active": is_active_support_changing,
                    "weak": is_weak_replacement,
                    "true_rc": true_rc,
                },
            )
        )
    ranked.sort(key=lambda item: item[0])
    if normalized_mode == "require_new_or_active_support":
        ranked = [
            item
            for item in ranked
            if bool(item[2]["new"]) or bool(item[2]["active"])
        ]
    before_rc_threshold = len(ranked)
    if threshold_enabled:
        ranked = [
            item
            for item in ranked
            if float(item[2]["true_rc"]) <= threshold + 1.0e-12
        ]
    rc_threshold_dropped_count = max(0, before_rc_threshold - len(ranked))
    if int(max_columns) > 0:
        ranked = ranked[: int(max_columns)]
    selected = [item[1] for item in ranked]
    stats = {
        "selected_new_task_set_count": sum(int(item[2]["new"]) for item in ranked),
        "selected_replacement_task_set_count": sum(int(item[2]["replacement"]) for item in ranked),
        "selected_active_support_changing_count": sum(int(item[2]["active"]) for item in ranked),
        "selected_weak_replacement_count": sum(int(item[2]["weak"]) for item in ranked),
    }
    selected_best_true_rc = (
        min(float(item[2]["true_rc"]) for item in ranked)
        if ranked
        else None
    )
    dropped = max(0, len(journeys) - len(selected))
    if not selected:
        filtered = replace(
            pricing,
            journeys=[],
            exhausted=False,
            selected_trips=0,
            status="INCOMPLETE",
            reason="sharded_pulse_hidden_negative_worker_impact_filtered_empty",
            global_certificate_capable=False,
            final_judge_certificate_capable=False,
            pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
            final_judge_incomplete_reason="impact_filtered_empty",
            pulse_negative_found=False,
        )
        _journey_sharded_pulse_worker_set_impact_attrs(
            filtered,
            enabled=True,
            mode=normalized_mode,
            candidate_count=len(journeys),
            selected_count=0,
            dropped_count=dropped,
            min_true_rc=threshold if threshold_enabled else None,
            selected_best_true_rc=None,
            rc_threshold_dropped_count=rc_threshold_dropped_count,
            **stats,
        )
        return filtered
    filtered = replace(
        pricing,
        journeys=selected,
        selected_trips=len(selected),
        best_reduced_cost=selected_best_true_rc,
    )
    _journey_sharded_pulse_worker_set_impact_attrs(
        filtered,
        enabled=True,
        mode=normalized_mode,
        candidate_count=len(journeys),
        selected_count=len(selected),
        dropped_count=dropped,
        min_true_rc=threshold if threshold_enabled else None,
        selected_best_true_rc=selected_best_true_rc,
        rc_threshold_dropped_count=rc_threshold_dropped_count,
        **stats,
    )
    return filtered


def _journey_sharded_pulse_worker_set_impact_attrs(
    pricing: JourneyPricingResult,
    *,
    enabled: bool,
    mode: str,
    candidate_count: int,
    selected_count: int,
    dropped_count: int,
    selected_new_task_set_count: int,
    selected_replacement_task_set_count: int,
    selected_active_support_changing_count: int,
    selected_weak_replacement_count: int,
    min_true_rc: float | None,
    selected_best_true_rc: float | None,
    rc_threshold_dropped_count: int,
) -> None:
    setattr(pricing, "pulse_worker_impact_filter_enabled", bool(enabled))
    setattr(pricing, "pulse_worker_impact_filter_mode", str(mode))
    setattr(pricing, "pulse_worker_impact_filter_candidate_count", int(candidate_count))
    setattr(pricing, "pulse_worker_impact_filter_selected_count", int(selected_count))
    setattr(pricing, "pulse_worker_impact_filter_dropped_count", int(dropped_count))
    setattr(
        pricing,
        "pulse_worker_impact_filter_selected_new_task_set_count",
        int(selected_new_task_set_count),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_selected_replacement_task_set_count",
        int(selected_replacement_task_set_count),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_selected_active_support_changing_count",
        int(selected_active_support_changing_count),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_selected_weak_replacement_count",
        int(selected_weak_replacement_count),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_min_true_rc",
        None if min_true_rc is None else float(min_true_rc),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_selected_best_true_rc",
        None if selected_best_true_rc is None else float(selected_best_true_rc),
    )
    setattr(
        pricing,
        "pulse_worker_impact_filter_rc_threshold_dropped_count",
        int(rc_threshold_dropped_count),
    )


def _journey_sharded_pulse_worker_followup_reserve_filtered(
    pricing: JourneyPricingResult,
    *,
    min_followup_time: float,
    remaining_after_worker: float | None,
) -> JourneyPricingResult:
    reserve = max(0.0, float(min_followup_time))
    if reserve <= 0.0:
        return pricing
    remaining = None if remaining_after_worker is None else max(0.0, float(remaining_after_worker))
    setattr(pricing, "pulse_worker_followup_reserve_min_time", float(reserve))
    setattr(pricing, "pulse_worker_followup_reserve_remaining_time", remaining)
    setattr(pricing, "pulse_worker_followup_reserve_dropped_journeys", 0)
    if remaining is None or remaining >= reserve or not list(getattr(pricing, "journeys", []) or []):
        return pricing

    dropped = len(getattr(pricing, "journeys", []) or [])
    filtered = replace(
        pricing,
        journeys=[],
        exhausted=False,
        selected_trips=0,
        status="INCOMPLETE",
        reason="sharded_pulse_hidden_negative_worker_followup_reserve",
        global_certificate_capable=False,
        final_judge_certificate_capable=False,
        pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
        final_judge_incomplete_reason="worker_followup_reserve",
        pulse_negative_found=False,
    )
    dynamic_attrs = (
        "pulse_worker_impact_filter_enabled",
        "pulse_worker_impact_filter_mode",
        "pulse_worker_impact_filter_candidate_count",
        "pulse_worker_impact_filter_selected_count",
        "pulse_worker_impact_filter_dropped_count",
        "pulse_worker_impact_filter_selected_new_task_set_count",
        "pulse_worker_impact_filter_selected_replacement_task_set_count",
        "pulse_worker_impact_filter_selected_active_support_changing_count",
        "pulse_worker_impact_filter_selected_weak_replacement_count",
        "pulse_worker_impact_filter_min_true_rc",
        "pulse_worker_impact_filter_selected_best_true_rc",
        "pulse_worker_impact_filter_rc_threshold_dropped_count",
    )
    for attr in dynamic_attrs:
        if hasattr(pricing, attr):
            setattr(filtered, attr, getattr(pricing, attr))
    setattr(filtered, "pulse_worker_followup_reserve_min_time", float(reserve))
    setattr(filtered, "pulse_worker_followup_reserve_remaining_time", float(remaining))
    setattr(filtered, "pulse_worker_followup_reserve_dropped_journeys", int(dropped))
    return filtered


def _run_journey_sharded_pulse_hidden_negative_worker(
    data: FutureData,
    config: dict[str, Any],
    logger: FutureLogger,
    *,
    duals: JourneyDuals,
    branch_constraints: tuple[BranchConstraint, ...],
    cuts: tuple[FutureCut, ...],
    journey_pool: JourneyPool,
    base_pricing_config: JourneyPricingConfig,
    cg_iter: int,
    node_id: int = 0,
    depth: int = 0,
    active_task_sets: set[frozenset[int]] | frozenset[frozenset[int]] | None = None,
    certificate_candidate: bool = False,
    remaining_time: float | None = None,
    previous_audit_signal: bool = False,
    previous_audit_context_hashes: dict[str, str] | None = None,
    certificate_flat_rounds: int = 0,
    certificate_no_column_rounds: int = 0,
) -> tuple[JourneyPricingResult, JourneyPricingConfig] | None:
    if not bool(config.get("journey_sharded_pulse_hidden_negative_worker_enabled", False)):
        return None
    trigger = str(
        config.get(
            "journey_sharded_pulse_hidden_negative_worker_trigger",
            config.get("journey_sharded_pulse_worker_trigger", "before_legacy_final_judge"),
        )
        or ""
    ).strip().lower()
    if trigger not in {
        "before_legacy_final_judge",
        "hard_tail_only",
        "audit_signal_or_current_probe",
    }:
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason="invalid_trigger",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None
    if bool(getattr(base_pricing_config, "sharded_final_judge_enabled", False)):
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason="base_pricing_is_sharded",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None
    max_cg_iter = max(
        0,
        int(config.get("journey_sharded_pulse_hidden_negative_worker_max_cg_iter", 0)),
    )
    if max_cg_iter > 0 and int(cg_iter) > int(max_cg_iter):
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason="max_cg_iter_exceeded",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None
    forbidden_signatures = _journey_forbidden_signatures_for_node(journey_pool, branch_constraints)
    context_hashes = _journey_sharded_pulse_audit_context_hashes(
        data,
        duals,
        branch_constraints,
        cuts,
        forbidden_signatures,
    )
    signal_source = "ungated" if trigger == "before_legacy_final_judge" else "none"
    expected_context_allowed, expected_context_skip_reason = (
        _journey_sharded_pulse_expected_context_allows(config, context_hashes)
    )
    expected_context_matched = _journey_sharded_pulse_expected_context_configured_match(
        config,
        context_hashes,
    )
    expected_context_current_probe_signal = bool(
        trigger == "audit_signal_or_current_probe"
        and expected_context_matched
        and bool(
            config.get(
                "journey_sharded_pulse_worker_current_probe_allow_expected_context_without_certificate_candidate",
                False,
            )
        )
    )
    if not bool(expected_context_allowed):
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason=expected_context_skip_reason,
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
            context_hashes=context_hashes,
            signal_source=signal_source,
            previous_audit_signal=previous_audit_signal,
        )
        return None
    use_current_probe_config = False
    current_probe_signal_source = (
        "expected_context_current_probe"
        if expected_context_current_probe_signal
        else "current_context_probe"
    )
    post_call_reserve = max(
        0.0,
        float(
            config.get(
                "journey_sharded_pulse_hidden_negative_worker_post_call_time_reserve",
                0.0,
            )
        ),
    )
    worker_available_time = None if remaining_time is None else max(
        0.0,
        float(remaining_time) - float(post_call_reserve),
    )
    if remaining_time is not None and float(post_call_reserve) > 0.0 and worker_available_time <= 0.0:
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason="post_call_reserve_too_low",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
            context_hashes=context_hashes,
            previous_audit_signal=previous_audit_signal,
        )
        return None
    min_followup_after_add = max(
        0.0,
        float(
            config.get(
                "journey_sharded_pulse_hidden_negative_worker_min_followup_time_after_add",
                0.0,
            )
        ),
    )
    if remaining_time is not None and min_followup_after_add > 0.0 and float(remaining_time) <= min_followup_after_add:
        _log_journey_sharded_pulse_worker_skipped(
            logger,
            config,
            skip_reason="followup_reserve_too_low",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
            context_hashes=context_hashes,
            previous_audit_signal=previous_audit_signal,
        )
        return None
    if trigger in {"hard_tail_only", "audit_signal_or_current_probe"}:
        if not bool(certificate_candidate) and not bool(expected_context_current_probe_signal):
            _log_journey_sharded_pulse_worker_skipped(
                logger,
                config,
                skip_reason="not_certificate_candidate",
                trigger=trigger,
                cg_iter=cg_iter,
                node_id=node_id,
                depth=depth,
                context_hashes=context_hashes,
                previous_audit_signal=previous_audit_signal,
            )
            return None
        min_tasks = int(config.get("journey_sharded_pulse_hidden_negative_worker_min_tasks", 6))
        if len(tuple(data.tasks)) < max(0, min_tasks):
            _log_journey_sharded_pulse_worker_skipped(
                logger,
                config,
                skip_reason="instance_too_small",
                trigger=trigger,
                cg_iter=cg_iter,
                node_id=node_id,
                depth=depth,
                context_hashes=context_hashes,
                previous_audit_signal=previous_audit_signal,
            )
            return None
        min_remaining = float(
            config.get("journey_sharded_pulse_hidden_negative_worker_min_remaining_time", 0.0)
        )
        if remaining_time is not None and float(remaining_time) < max(0.0, min_remaining):
            _log_journey_sharded_pulse_worker_skipped(
                logger,
                config,
                skip_reason="time_remaining_too_low",
                trigger=trigger,
                cg_iter=cg_iter,
                node_id=node_id,
                depth=depth,
                context_hashes=context_hashes,
                previous_audit_signal=previous_audit_signal,
            )
            return None
        if bool(previous_audit_signal) and previous_audit_context_hashes:
            previous_context = str(previous_audit_context_hashes.get("context", ""))
            current_context = str(context_hashes.get("context", ""))
            if previous_context and current_context and previous_context != current_context:
                _log_journey_sharded_pulse_worker_skipped(
                    logger,
                    config,
                    skip_reason="audit_context_mismatch",
                    trigger=trigger,
                    cg_iter=cg_iter,
                    node_id=node_id,
                    depth=depth,
                    context_hashes=context_hashes,
                    signal_source="previous_audit",
                    previous_audit_signal=True,
                )
                return None
        if bool(previous_audit_signal):
            signal_source = "previous_audit"
        elif trigger == "audit_signal_or_current_probe":
            if not bool(config.get("journey_sharded_pulse_worker_current_probe_enabled", False)):
                _log_journey_sharded_pulse_worker_skipped(
                    logger,
                    config,
                    skip_reason="no_previous_audit_negative_signal",
                    trigger=trigger,
                    cg_iter=cg_iter,
                    node_id=node_id,
                    depth=depth,
                    context_hashes=context_hashes,
                    previous_audit_signal=False,
                )
                return None
            probe_min_tasks = int(
                config.get("journey_sharded_pulse_worker_current_probe_min_tasks", 10)
            )
            if len(tuple(data.tasks)) < max(0, probe_min_tasks):
                _log_journey_sharded_pulse_worker_skipped(
                    logger,
                    config,
                    skip_reason="current_probe_instance_too_small",
                    trigger=trigger,
                    cg_iter=cg_iter,
                    node_id=node_id,
                    depth=depth,
                    context_hashes=context_hashes,
                    signal_source=current_probe_signal_source,
                    previous_audit_signal=False,
                )
                return None
            probe_min_remaining = float(
                config.get("journey_sharded_pulse_worker_current_probe_min_remaining_time", 8.0)
            )
            if remaining_time is not None and float(remaining_time) < max(0.0, probe_min_remaining):
                _log_journey_sharded_pulse_worker_skipped(
                    logger,
                    config,
                    skip_reason="current_probe_time_remaining_too_low",
                    trigger=trigger,
                    cg_iter=cg_iter,
                    node_id=node_id,
                    depth=depth,
                    context_hashes=context_hashes,
                    signal_source=current_probe_signal_source,
                    previous_audit_signal=False,
                )
                return None
            if not _journey_sharded_pulse_current_probe_hard_tail_fingerprint_allows(
                config,
                certificate_flat_rounds=certificate_flat_rounds,
                certificate_no_column_rounds=certificate_no_column_rounds,
            ):
                _log_journey_sharded_pulse_worker_skipped(
                    logger,
                    config,
                    skip_reason="current_probe_hard_tail_fingerprint_missing",
                    trigger=trigger,
                    cg_iter=cg_iter,
                    node_id=node_id,
                    depth=depth,
                    context_hashes=context_hashes,
                    signal_source=current_probe_signal_source,
                    previous_audit_signal=False,
                )
                return None
            signal_source = current_probe_signal_source
            use_current_probe_config = True
        else:
            _log_journey_sharded_pulse_worker_skipped(
                logger,
                config,
                skip_reason="no_previous_audit_negative_signal",
                trigger=trigger,
                cg_iter=cg_iter,
                node_id=node_id,
                depth=depth,
                context_hashes=context_hashes,
                previous_audit_signal=False,
            )
            return None

    started = time.perf_counter()
    if use_current_probe_config:
        worker_time_limit = max(
            0.0,
            float(config.get("journey_sharded_pulse_worker_current_probe_time_limit", 1.0)),
        )
        if remaining_time is not None:
            worker_time_limit = min(
                worker_time_limit,
                max(0.0, float(worker_available_time if worker_available_time is not None else remaining_time)),
            )
        worker_config = _journey_sharded_pulse_current_probe_config(
            config,
            base_pricing_config,
            time_limit=worker_time_limit,
        )
    else:
        worker_time_limit = max(
            0.0,
            float(config.get("journey_sharded_pulse_hidden_negative_worker_time_limit", 3.0)),
        )
        if remaining_time is not None:
            worker_time_limit = min(
                worker_time_limit,
                max(0.0, float(worker_available_time if worker_available_time is not None else remaining_time)),
            )
        worker_config = _journey_sharded_pulse_hidden_negative_worker_config(
            config,
            base_pricing_config,
            time_limit=worker_time_limit,
        )
    true_rc_filtered = 0
    if worker_time_limit <= 0.0:
        pulse_pricing = JourneyPricingResult(
            [],
            False,
            None,
            0,
            0,
            0,
            0,
            "INCOMPLETE",
            "sharded_pulse_hidden_negative_worker_time_limit",
            pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
            final_judge_engine="sharded_pulse",
            final_judge_sharded_enabled=True,
            final_judge_incomplete_reason="worker_time_limit",
        )
    else:
        target_materialization_config = (
            _journey_sharded_pulse_target_materialization_config_for_context(
                config,
                context_hashes,
            )
        )
        target_pricing = _journey_sharded_pulse_target_materialization_result(
            data,
            target_materialization_config,
            duals=duals,
            cuts=cuts,
            base_pricing_config=worker_config,
            eps=float(config.get("eps", 1.0e-6)),
        )
        if target_pricing is not None:
            pulse_pricing = target_pricing
        else:
            try:
                pulse_pricing = price_journeys(
                    data,
                    duals,
                    branch_constraints,
                    config=worker_config,
                    cuts=cuts,
                    trip_cache={},
                    resource_cache={},
                    forbidden_journey_signatures=forbidden_signatures,
                    dominant_task_set_costs=_journey_pricing_dominant_task_set_costs(
                        journey_pool, cuts, branch_constraints
                    ),
                    priority_task_sets=active_task_sets,
                    active_support_task_sets=active_task_sets,
                )
            except Exception as exc:  # pragma: no cover - defensive worker shield.
                pulse_pricing = JourneyPricingResult(
                    [],
                    False,
                    None,
                    0,
                    0,
                    0,
                    0,
                    "INCOMPLETE",
                    f"sharded_pulse_hidden_negative_worker_internal_error:{type(exc).__name__}",
                    pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
                    final_judge_engine="sharded_pulse",
                    final_judge_sharded_enabled=True,
                    final_judge_incomplete_reason="worker_internal_error",
                )
        pulse_pricing, true_rc_filtered = _journey_sharded_pulse_hidden_negative_worker_sanitize(
            pulse_pricing,
            duals,
            cuts,
            eps=float(config.get("eps", 1.0e-6)),
        )
        pulse_pricing = _journey_sharded_pulse_worker_impact_filtered(
            pulse_pricing,
            journey_pool=journey_pool,
            active_task_sets=active_task_sets,
            duals=duals,
            cuts=cuts,
            mode=str(
                config.get(
                    "journey_sharded_pulse_hidden_negative_worker_impact_filter_mode",
                    "off",
                )
                or "off"
            ),
            max_columns=int(
                config.get(
                    "journey_sharded_pulse_hidden_negative_worker_impact_filter_max_columns",
                    0,
                )
            ),
            min_true_rc=float(
                config.get(
                    "journey_sharded_pulse_hidden_negative_worker_impact_filter_min_true_rc",
                    0.0,
                )
            ),
        )
    elapsed = time.perf_counter() - started
    remaining_after_worker = None
    if remaining_time is not None:
        remaining_after_worker = max(0.0, float(remaining_time) - float(elapsed))
    pulse_pricing = _journey_sharded_pulse_worker_followup_reserve_filtered(
        pulse_pricing,
        min_followup_time=min_followup_after_add,
        remaining_after_worker=remaining_after_worker,
    )
    logger.log(
        "journey_sharded_pulse_hidden_negative_worker",
        node_id=int(node_id),
        depth=int(depth),
        cg_iter=int(cg_iter),
        pulse_worker_trigger=trigger,
        pulse_worker_signal_source=signal_source,
        pulse_worker_skipped=False,
        pulse_worker_skip_reason="",
        pulse_worker_previous_audit_signal=bool(previous_audit_signal),
        pulse_worker_current_probe_signal=bool(
            signal_source in {"current_context_probe", "expected_context_current_probe"}
            and _journey_pricing_state(pulse_pricing) == PRICING_STATE_FOUND_NEGATIVE
            and bool(getattr(pulse_pricing, "journeys", []) or [])
        ),
        pulse_worker_allow_certificate_effect=False,
        **_journey_sharded_pulse_hidden_negative_worker_payload(
            pulse_pricing,
            elapsed=elapsed,
            context_hashes=context_hashes,
            true_rc_filtered=true_rc_filtered,
        ),
    )
    return pulse_pricing, worker_config


def _run_journey_sharded_pulse_audit(
    data: FutureData,
    config: dict[str, Any],
    logger: FutureLogger,
    *,
    legacy_pricing: Any,
    legacy_duals: JourneyDuals,
    branch_constraints: tuple[BranchConstraint, ...],
    cuts: tuple[FutureCut, ...],
    journey_pool: JourneyPool,
    base_pricing_config: JourneyPricingConfig,
    cg_iter: int,
    node_id: int = 0,
    depth: int = 0,
    active_task_sets: set[frozenset[int]] | frozenset[frozenset[int]] | None = None,
    trigger: str = "after_legacy_final_judge",
) -> Any | None:
    allowed, skip_reason = _journey_sharded_pulse_audit_trigger_allows(
        config,
        trigger=trigger,
        depth=depth,
    )
    if not allowed:
        _log_journey_sharded_pulse_audit_skipped(
            logger,
            config,
            skip_reason=skip_reason,
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None
    if not bool(config.get("journey_sharded_pulse_audit_after_legacy_final_judge", True)):
        _log_journey_sharded_pulse_audit_skipped(
            logger,
            config,
            skip_reason="not_after_legacy_final_judge",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None
    if bool(getattr(base_pricing_config, "sharded_final_judge_enabled", False)):
        _log_journey_sharded_pulse_audit_skipped(
            logger,
            config,
            skip_reason="base_pricing_is_sharded",
            trigger=trigger,
            cg_iter=cg_iter,
            node_id=node_id,
            depth=depth,
        )
        return None

    started = time.perf_counter()
    forbidden_signatures = _journey_forbidden_signatures_for_node(journey_pool, branch_constraints)
    context_hashes = _journey_sharded_pulse_audit_context_hashes(
        data,
        legacy_duals,
        branch_constraints,
        cuts,
        forbidden_signatures,
    )
    audit_time_limit = max(
        0.0,
        float(config.get("journey_sharded_pulse_audit_time_limit", 5.0)),
    )
    if audit_time_limit <= 0.0:
        pulse_pricing = JourneyPricingResult(
            [],
            False,
            None,
            0,
            0,
            0,
            0,
            "INCOMPLETE",
            "pulse_audit_time_limit",
            pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
            final_judge_engine="sharded_pulse",
            final_judge_sharded_enabled=True,
            final_judge_incomplete_reason="audit_time_limit",
        )
    else:
        audit_config = _journey_sharded_pulse_audit_config(
            config,
            base_pricing_config,
            time_limit=audit_time_limit,
        )
        try:
            pulse_pricing = price_journeys(
                data,
                legacy_duals,
                branch_constraints,
                config=audit_config,
                cuts=cuts,
                trip_cache={},
                resource_cache={},
                forbidden_journey_signatures=forbidden_signatures,
                dominant_task_set_costs=_journey_pricing_dominant_task_set_costs(
                    journey_pool, cuts, branch_constraints
                ),
                priority_task_sets=active_task_sets,
                active_support_task_sets=active_task_sets,
            )
        except Exception as exc:  # pragma: no cover - defensive audit-only shield.
            pulse_pricing = JourneyPricingResult(
                [],
                False,
                None,
                0,
                0,
                0,
                0,
                "INCOMPLETE",
                f"pulse_audit_internal_error:{type(exc).__name__}",
                pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
                final_judge_engine="sharded_pulse",
                final_judge_sharded_enabled=True,
                final_judge_incomplete_reason="audit_internal_error",
            )
    elapsed = time.perf_counter() - started
    audit_payload = _journey_sharded_pulse_audit_payload(
        legacy_pricing,
        pulse_pricing,
        elapsed=elapsed,
        context_hashes=context_hashes,
    )
    try:
        setattr(pulse_pricing, "_sharded_pulse_audit_payload", audit_payload)
        setattr(pulse_pricing, "_sharded_pulse_audit_context_hashes", dict(context_hashes))
    except Exception:
        pass
    if bool(config.get("journey_sharded_pulse_audit_log_disagreements", True)) or not audit_payload[
        "pulse_audit_agrees_with_legacy"
    ]:
        logger.log(
            "journey_sharded_pulse_audit",
            node_id=int(node_id),
            depth=int(depth),
            cg_iter=int(cg_iter),
            pulse_audit_skipped=False,
            pulse_audit_skip_reason="",
            pulse_audit_trigger=str(trigger),
            pulse_audit_allow_certificate_effect=bool(
                config.get("journey_sharded_pulse_audit_allow_certificate_effect", False)
            ),
            **audit_payload,
        )
    return pulse_pricing


